/* B4~M4L documentation language support. Source is English; translations are editorial drafts. */
(()=>{'use strict';
const translations={"it":{"MAX FOR LIVE DEVICES.":"DISPOSITIVI MAX FOR LIVE.","DOCUMENTATION, CHANGELOGS AND EVERYTHING YOU NEED TO KNOW. WITHOUT THE FLUFF.":"DOCUMENTAZIONE, CHANGELOG E TUTTO QUELLO CHE SERVE SAPERE. SENZA FRONZOLI.","DEVICES":"DISPOSITIVI","Explore the device":"Esplora il dispositivo","CORE IMAGE PENDING":"IMMAGINE CORE IN ARRIVO","CORE SCREENSHOT / PENDING":"SCREENSHOT CORE / IN ARRIVO","Testing · Staging · Not distributed":"Test · Staging · Non distribuito","TESTING · STAGING · NOT DISTRIBUTED":"TEST · STAGING · NON DISTRIBUITO","Two distinct modulation signals from audio: one follows the moment, the other follows the time it lasts.":"Due segnali di modulazione distinti dall’audio: uno segue l’istante, l’altro la sua durata.","← ALL DEVICES":"← TUTTI I DISPOSITIVI","HELP":"GUIDA","SUPPORT":"SUPPORTO","Support":"Supporto","Quick":"Inizio","Quick start":"Primi passi","Trouble":"Problemi","Troubleshooting":"Risoluzione problemi","Under":"Tecnica","Under the hood":"Come funziona","Layers":"Livelli","Params":"Parametri","Parameters":"Parametri","Color":"Colore","Library":"Libreria","Performance":"Prestazioni","Main":"Principale","Time":"Tempo","Behaviors":"Comportamenti","Mapping":"Mappatura","01 / REQUIREMENTS":"01 / REQUISITI","COMPATIBILITY":"COMPATIBILITÀ","02 / VERSION HISTORY":"02 / CRONOLOGIA VERSIONI","03 / DOCUMENTATION":"03 / DOCUMENTAZIONE","HELP & GUIDES ↓":"GUIDE E MANUALI ↓","PUBLIC RELEASE NOTES":"NOTE DI RILASCIO PUBBLICHE","REPORT AN ISSUE":"SEGNALA UN PROBLEMA","Report an issue or get in touch.":"Segnala un problema o contattami.","Having trouble with INDEX HTML BRIDGE? Get in touch.":"Problemi con INDEX HTML BRIDGE? Scrivimi.","Having trouble with CONSEQUENCE OF TIME? Get in touch.":"Problemi con CONSEQUENCE OF TIME? Scrivimi.","DEVICE SCREENSHOT / PENDING":"SCREENSHOT DISPOSITIVO / IN ARRIVO","MAXFORLIVE PROFILE":"PROFILO MAXFORLIVE","TEST ENVIRONMENT":"AMBIENTE DI TEST","PLATFORM":"PIATTAFORMA","DISTRIBUTION":"DISTRIBUZIONE","Not yet cleared":"Non ancora approvata","Two independent modulation signals from one audio input: A follows intensity, B grows with recognized contact time. Shape both in Ableton Live.":"Due segnali di modulazione indipendenti da un solo ingresso audio: A segue l’intensità, B cresce con la durata del contatto rilevato. Modellali entrambi in Ableton Live.","Established development target; exact minimum release version is not certified.":"Ambiente di sviluppo di riferimento; la versione minima esatta non è ancora certificata.","Intel and Apple Silicon environments have been used in development. This candidate still requires acceptance. Windows untested.":"Lo sviluppo ha coinvolto Mac Intel e Apple Silicon. Questa build richiede ancora l’accettazione; Windows non è stato testato.","0.1.5.0 tested partially with Live 12.4.2 and bundled Max 9.1.4. These are not certified minimum requirements.":"0.1.5.0 testata parzialmente con Live 12.4.2 e Max 9.1.4 integrato. Non sono requisiti minimi certificati.","macOS development testing":"Test di sviluppo su macOS","Apple Silicon tests on 0.1.5.0 are partial. Separate Intel tests apply to 0.1.4.3, not this candidate. Windows untested.":"I test Apple Silicon della 0.1.5.0 sono parziali. I test Intel riguardano la 0.1.4.3, non questa candidata. Windows non testato.","Packaging, portability and redistribution requirements remain unresolved. No public release is being offered here.":"Packaging, portabilità e condizioni di redistribuzione sono ancora da verificare. Nessuna release pubblica è disponibile qui.","No publicly distributed release has been verified for this documentation snapshot. The manual below references the":"Non risultano release pubbliche verificate per questa documentazione. Il manuale seguente fa riferimento alla","0.23.9-rc.3 testing candidate":"build candidata di test 0.23.9-rc.3","; release candidate notes are not published as commercial release history.":"; le note delle RC non sono presentate come cronologia di release commerciali.","No public release is currently confirmed. This documentation is a":"Non è confermata alcuna release pubblica. Questa documentazione è una","draft based on testing candidate 0.1.5.0":"bozza basata sulla build candidata 0.1.5.0","; internal milestones are deliberately excluded from public release notes.":"; le milestone interne sono escluse intenzionalmente dalle note pubbliche.","Documentation draft — review before first public release.":"Bozza documentale — da approvare prima del rilascio pubblico.","WEBSITE":"SITO WEB","EXTERNAL SERVICES":"SERVIZI ESTERNI","LANGUAGE PREFERENCE":"PREFERENZA LINGUISTICA","SUPPORT EMAIL":"EMAIL DI SUPPORTO","CONTROLLER / CONTACT":"TITOLARE / CONTATTI","B4~M4L is a static documentation website. The current site code contains no first-party analytics, advertising pixels, forms or user accounts.":"B4~M4L è un sito statico di documentazione. Il codice attuale non include analisi proprietarie, pixel pubblicitari, moduli né account utente.","The site is intended to be hosted with GitHub Pages. GitHub may process visitor data, including IP addresses, under its own privacy statement.":"Il sito sarà ospitato su GitHub Pages. GitHub può trattare dati dei visitatori, inclusi gli indirizzi IP, secondo la propria informativa.","GitHub Privacy Statement":"Informativa privacy di GitHub","The REPORT AN ISSUE button opens your email application using a prefilled message. B4~M4L does not automatically transmit attachments or diagnostics. Any information you choose to send by email is handled through the email services involved.":"Il pulsante SEGNALA UN PROBLEMA apre l’app email con un messaggio precompilato. B4~M4L non invia automaticamente allegati o diagnostica. Le informazioni inviate volontariamente sono gestite dai servizi email coinvolti.","Development reference only · final installation workflow to be verified on the distributed build.":"Riferimento di sviluppo: il flusso di installazione definitivo dovrà essere verificato sulla build distribuita.","Send some audio":"Invia un segnale audio","Load COT onto an audio track in Live, or select an external sidechain source.":"Carica COT su una traccia audio in Live oppure seleziona una sorgente sidechain esterna.","Watch A and B":"Osserva A e B","A follows current intensity. B develops while contact is recognized.":"A segue l’intensità corrente. B si sviluppa finché viene riconosciuto il contatto.","Shape the signals":"Modella i segnali","Use AUDIO to set A response. Use TIME for Window, Growth, Accel and B Attack/Hold/Decay.":"Usa AUDIO per la risposta di A e TIME per Window, Growth, Accel e Attack/Hold/Decay di B.","Map two destinations":"Mappa due destinazioni","Assign A and B separately in Live, and compare Mod with Remote behavior.":"Assegna A e B separatamente in Live e confronta i comportamenti Mod e Remote.","Try behaviors":"Prova i comportamenti","Start in CLEAN, then explore the seven other modes and their Time Amount controls.":"Parti da CLEAN, poi prova le altre sette modalità e i relativi controlli Time Amount.","Two independent modulation signals, one shared audio input.":"Due segnali di modulazione indipendenti, un ingresso audio condiviso.","A / Audio Signal":"A / Segnale audio","B / Time Signal":"B / Segnale temporale","Tracks audio intensity via an envelope follower. A ranges from 0 to 1 and responds relatively quickly to changes in the source.":"Segue l’intensità tramite un envelope follower. A varia da 0 a 1 e risponde abbastanza rapidamente ai cambiamenti della sorgente.","Accumulates recognized contact time. B also ranges from 0 to 1, but follows its own time engine, hold and decay.":"Accumula il tempo di contatto riconosciuto. Anche B varia da 0 a 1, ma segue un motore temporale indipendente, con hold e decay.","The scope":"Il display","The two traces represent separate signals; they are not combined. MIXED / Output C is not implemented in the documented testing build.":"Le due tracce rappresentano segnali separati, non sommati. MIXED / Output C non è implementato nella build di test documentata.","Shape the audio-responsive signal A.":"Modella il segnale A che risponde all’audio.","Audio source":"Sorgente audio","Use the main track input or select an external sidechain. Check routing when nothing moves.":"Usa l’ingresso della traccia oppure una sidechain esterna. Se non si muove nulla, verifica il routing.","Adjust incoming level before the signal is analyzed.":"Regola il livello in ingresso prima dell’analisi.","Set how quickly signal A reacts to increasing and decreasing audio intensity. These controls do not modify B Attack, Hold or Decay.":"Regola la velocità di risposta di A all’aumento e alla diminuzione dell’intensità audio. Non modifica Attack, Hold o Decay di B.","Adjust the amount applied to normalized A. It is not the contact threshold used by the time engine.":"Regola la quantità applicata ad A normalizzato. Non è la soglia di contatto del motore temporale.","Build a time-driven signal B from recognized contact.":"Costruisci il segnale temporale B a partire dal contatto riconosciuto.","Contact threshold":"Soglia di contatto","audio-intensity threshold (%)":"soglia di intensità audio (%)","Allows short gaps beneath the threshold without immediately ending contact. After contact really ends, B proceeds to Hold and then Decay.":"Tollera brevi interruzioni sotto soglia senza terminare subito il contatto. Dopo la fine effettiva, B passa a Hold e poi a Decay.","Choose BEATS (musical tempo) or TIME (elapsed time) as the accumulation window; the two modes retain separate values.":"Scegli BEATS (tempo musicale) o TIME (tempo trascorso) come finestra di accumulo; le due modalità conservano valori separati.","Growth changes accumulation rate. Negative Accel gradually slows forward progress without reversing time. The reference build uses an Accel range of −4…+4.":"Growth cambia la velocità di accumulo. Accel negativo rallenta progressivamente senza invertire il tempo. La build di riferimento usa −4…+4 per Accel.","Set initial signal level and range of movement.":"Imposta il livello iniziale del segnale e la sua escursione.","Attack smooths growth, Hold keeps the value after contact is lost, Decay returns B toward zero.":"Attack smussa la crescita, Hold mantiene il valore dopo la perdita di contatto, Decay riporta B verso zero.","Eight ways to reshape B over time.":"Otto modi per trasformare B nel tempo.","Pure time evolution. Time Amount has no effect in CLEAN.":"Evoluzione temporale pura. Time Amount non ha effetto in CLEAN.","Changes movement range in response to intensity.":"Modifica l’escursione in risposta all’intensità.","Changes accumulation speed in response to intensity.":"Modifica la velocità di accumulo in risposta all’intensità.","Adds signal-dependent irregular fluctuations.":"Aggiunge oscillazioni irregolari dipendenti dal segnale.","May produce a descending positive curve, not negative output; transitions can be abrupt.":"Può generare una curva positiva discendente, non un’uscita negativa; le transizioni possono essere brusche.","Can pause time progress when intensity meets its condition.":"Può sospendere l’avanzamento temporale quando l’intensità soddisfa la condizione.","Quantizes the time signal into discrete steps.":"Quantizza il segnale temporale in passi discreti.","Combines speed changes and irregular fluctuations. Time Amount adjusts each active behavior, not the basic B Depth.":"Combina variazioni di velocità e oscillazioni irregolari. Time Amount regola ogni comportamento attivo, non B Depth di base.","Connect A and B to separate Live destinations.":"Collega A e B a destinazioni Live indipendenti.","A and B mapping":"Mappatura A e B","Map A and B independently to parameters in Ableton Live using the device mapping controls.":"Associa A e B a parametri diversi di Ableton Live usando i controlli di mappatura del device.","Mod works as relative modulation around a parameter base value. Remote takes exclusive control of its destination. These are native Ableton behaviors.":"Mod modula relativamente al valore di base del parametro. Remote ne assume il controllo esclusivo. Sono comportamenti nativi di Ableton.","Save & Reload":"Salvataggio e riapertura","After mapping, verify actual modulation after saving and reopening the Live Set — not only that the destination name persists.":"Dopo la mappatura, salva e riapri il Live Set e verifica che la modulazione funzioni davvero, non soltanto che sia presente il nome della destinazione.","Distribution note":"Nota sulla distribuzione","The referenced testing build uses native Ableton mapping abstractions with unresolved distribution/portability requirements. Do not use it as an installation guide for a public release.":"La build di test usa astrazioni Ableton per il mapping i cui requisiti di distribuzione/portabilità sono irrisolti. Non usarla come guida per installare una release pubblica.","Choose a separate source for audio analysis.":"Scegli una sorgente separata per l’analisi audio.","Main audio":"Audio principale","External sidechain":"Sidechain esterna","Choose an appropriate external source in Live, confirm routing, then watch the two traces in MAIN.":"Scegli una sorgente esterna in Live, verifica il routing e osserva le due tracce in MAIN.","Reference layout":"Layout di riferimento","The sidechain panel appears to the right in 0.1.5.0. Its planned relocation is not reflected in this guide.":"Nella 0.1.5.0 il pannello sidechain compare a destra. Il futuro spostamento non è ancora documentato qui.","Common checks for signal, timing and mapping.":"Controlli comuni su segnale, tempo e mappatura.","No signal movement":"Nessun movimento del segnale","Confirm that audio is present, inspect source and routing, increase Gain as appropriate, and check the contact threshold and B Depth.":"Verifica che l’audio sia presente, controlla sorgente e routing, regola Gain e verifica soglia di contatto e B Depth.","A moves but B does not":"A si muove ma B no","Check the threshold and Tolerance, the Window, Growth, B Start/Depth and whether sufficient contact time has accumulated.":"Controlla soglia, Tolerance, Window, Growth e B Start/Depth, e verifica che si accumuli abbastanza tempo di contatto.","Mapping looks static":"La mappatura sembra ferma","In Mod mode, the base knob may stay at its set value while modulation operates. Check the destination response, not only the knob position.":"In modalità Mod, il knob base può rimanere fermo mentre la modulazione agisce. Verifica la destinazione, non solo la posizione del knob.","Migration to another Mac":"Trasferimento su un altro Mac","Portability has not been cleared for 0.1.5.0. Do not treat the development patch as an installer or redistribution package.":"La portabilità della 0.1.5.0 non è stata approvata. Non considerare la patch di sviluppo un installer o un pacchetto distribuibile.","How the two modulation signals differ.":"Come differiscono i due segnali di modulazione.","A: amplitude response":"A: risposta all’ampiezza","The envelope follower translates the level of the input signal into a continuous normalized modulation output.":"L’envelope follower trasforma il livello d’ingresso in un’uscita di modulazione continua e normalizzata.","B: duration response":"B: risposta alla durata","Contact recognition drives a separate time engine. Window, Growth, Accel, Hold, Decay and Behavior change the shape of B.":"Il rilevamento del contatto controlla un motore temporale separato. Window, Growth, Accel, Hold, Decay e Behavior plasmano B.","No Output C yet":"Output C non disponibile","MAIN displays separate A and B traces. A blended third modulation signal is a future idea, not a current feature.":"MAIN visualizza le tracce separate A e B. Un terzo segnale combinato è un’idea futura, non una funzione attuale.","Audio transparency":"Trasparenza audio","Help manifest unavailable.":"Manifest HELP non disponibile.","Open this page through the B4~M4L local server or check that the documentation manifest is present.":"Apri la pagina tramite il server locale di B4~M4L o verifica la presenza del manifest documentale.","Pick a layer":"Scegli un livello","Open L1–L5. Only one Layer editor is open at a time.":"Apri L1–L5. Può essere aperto un solo editor di Layer per volta.","Choose a tool":"Scegli un tool","Select it from the library, check its status, then LOAD / UPDATE / DOWNLOAD explicitly.":"Selezionalo nella libreria, controlla lo stato, poi esegui LOAD / UPDATE / DOWNLOAD manualmente.","Shape it":"Modellalo","Open PARAMETERS, COLORS & BLEND and MIDI MAPPING in any combination.":"Apri PARAMETERS, COLORS & BLEND e MIDI MAPPING nella combinazione che preferisci.","Render live":"Renderizza live","RENDER opens the external Chromium compositor. Your five Layers are combined there.":"RENDER apre il compositore Chromium esterno, nel quale vengono combinati i cinque Layer.","Five independent visual slots, composed from L1 upward. Effects process only what sits below them.":"Cinque slot visual indipendenti, composti a partire da L1. Gli effetti elaborano solo i livelli sottostanti.","One editor, five layers":"Un editor, cinque livelli","Tool loading":"Caricamento tool","Generator vs effect":"Generatore o effetto","Remembered per layer":"Memoria per livello","Native Live parameters":"Parametri Live nativi","Reset & defaults":"Reset e valori predefiniti","Effective values":"Valori effettivi","Automation stays yours":"L’automazione resta tua","Colors & Blend":"Colori e blend","Effect Layers do not use generator blend in the same way: their shader processes the lower composite directly.":"Gli Effect Layer non usano il blend come i generatori: lo shader elabora direttamente la composizione sottostante.","MIDI Mapping":"Mappatura MIDI","Map NOTE or CC directly onto P01–P12 with amount and envelope/smoothing controls.":"Mappa NOTE o CC direttamente su P01–P12 con quantità e controlli di inviluppo/smoothing.","CHECK INDEX compares your local HTML tools with the INDEX catalogue. Nothing updates by itself.":"CHECK INDEX confronta i tool HTML locali con il catalogo INDEX. Nessun aggiornamento è automatico.","Status":"Stato","Selected tool":"Tool selezionato","Requirements":"Requisiti","Live output":"Output live","Live Render Performance":"Prestazioni del rendering live","Automatic panel":"Pannello automatico","Read the monitor":"Leggi il monitor","Same view, different quality":"Stessa inquadratura, qualità diversa","1 · Acquire":"1 · Acquisizione","2 · Replay":"2 · Riproduzione","3 · Encode":"3 · Codifica","Current build note":"Nota sulla build corrente","Files and diagnostic reports":"File e report diagnostici","Current output options":"Opzioni di output attuali","Second pass":"Secondo passaggio","Files":"File","Video audio":"Audio del video","Testing status":"Stato dei test","The useful failure boundaries, current limitations and what not to expect from this build.":"I punti di errore più utili, i limiti attuali e cosa non aspettarsi da questa build.","macOS security":"Sicurezza macOS","Clock and incomplete range":"Clock e intervallo incompleto","No final file / incomplete cleanup":"File finale assente / pulizia incompleta","Browser or missing resources":"Browser o risorse mancanti","Current limitations":"Limitazioni attuali","Only if you care: how Max, Node and Chromium divide the work.":"Per chi vuole approfondire: come Max, Node e Chromium si dividono il lavoro.","No Jitter renderer":"Nessun renderer Jitter","INDEX HTML stays browser-native. The fundamental split is simple: Max decides what happens; the browser decides how to draw it.":"INDEX HTML rimane nativo del browser. La distinzione è semplice: Max decide cosa accade; il browser decide come disegnarlo.","Links to":"Collegamenti a","and third-party websites open independent services. Their own privacy policies apply when you visit them. If you follow a link to Apple, see the":"e ad altri siti terzi aprono servizi indipendenti. Visitandoli, si applicano le rispettive informative. Se segui un collegamento Apple, consulta l’","Apple Privacy Policy":"informativa privacy di Apple","Matteo Belgiovine — Turin, Italy ·":"Matteo Belgiovine — Torino, Italia ·","Open one Layer editor at a time. Layer visibility is independent from whether its editor is open.":"Apri un editor di Layer alla volta. La visibilità di ciascun Layer è indipendente dall’apertura del suo editor.","Choosing a tool in the dropdown only selects it. Press LOAD to use the selection. A new LOAD restores manifest defaults. Keep tools/ and the complete device folder together; local INDEX_TOOL RC2 and legacy SKETCH_TOOL files work offline.":"Scegliere un tool nel menu lo seleziona soltanto: premi LOAD per caricarlo. Un nuovo LOAD ripristina i default del manifest. Mantieni insieme tools/ e l’intera cartella del device; i file INDEX_TOOL RC2 e i precedenti SKETCH_TOOL funzionano offline.","Generators draw their own canvas. Effects receive the composite of the Layers beneath them and process that result.":"I generatori disegnano sul proprio canvas. Gli effetti ricevono e modificano la composizione dei Layer sottostanti.","Each Layer remembers its section visibility. Saving a Live Set also stores the loaded tools, native values, HEX, mappings and device settings. Changing a tool resets its values: there is no separate preset memory for every tool. Keep the local tool files available when reopening a Set.":"Ogni Layer ricorda quali sezioni sono aperte. Il Live Set salva anche tool caricati, valori nativi, HEX, mappature e impostazioni. Cambiare tool ripristina i valori: non esiste una memoria preset per ciascun tool. Conserva i file locali quando riapri il Set.","Twelve numeric slots per Layer, mapped to each tool’s own manifest labels and ranges.":"Dodici slot numerici per Layer, con etichette e intervalli definiti dal manifest del tool.","The device exposes a stable Live parameter registry for automation and external modulation.":"Il device espone un registro stabile di parametri Live per automazione e modulazione esterna.","Use the single reset beside a parameter for that control only. DEFAULT restores the loaded tool’s manifest defaults.":"Usa il reset accanto al parametro per ripristinare solo quel controllo. DEFAULT ripristina i valori definiti dal manifest del tool caricato.","Up to four tool-defined colors, independent opacity and per-Layer blend mode.":"Fino a quattro colori definiti dal tool, opacità indipendenti e un blend mode per Layer.","Each active color can be edited with the picker or six-digit HEX input. Unused manifest slots stay clearly marked.":"Ogni colore attivo si modifica con il picker o inserendo un HEX a sei cifre. Gli slot non utilizzati sono segnalati chiaramente.","Color opacity is a native host control and does not consume P01–P12. Missing host opacity keeps the standalone tool behaviour unchanged.":"L’opacità è un controllo nativo dell’host e non occupa P01–P12. Se manca, il comportamento standalone del tool non cambia.","Velocity becomes the modulation peak. Attack rises to that peak, then release returns automatically to zero.":"La velocity determina il picco di modulazione. Attack raggiunge quel valore e Release torna automaticamente a zero.","The incoming 0–127 value becomes the target. Attack smooths upward movement; release smooths downward movement.":"Il valore CC in ingresso (0–127) diventa il target. Attack smussa la salita, Release la discesa.","Refreshes the remote catalogue and compares it with the flat local":"Aggiorna il catalogo remoto e lo confronta con la libreria locale","library. It does not download tools automatically.":": non scarica automaticamente i tool.","Depending on state, the action becomes LOAD, UPDATE or DOWNLOAD. A dropdown selection alone never changes the running Layer.":"In base allo stato, l’azione diventa LOAD, UPDATE o DOWNLOAD. La selezione dal menu non modifica mai il Layer in esecuzione.","Queues only MISSING and OUTDATED catalogue tools. CURRENT entries are left untouched; local-only fixtures remain local.":"Accoda soltanto tool MISSING e OUTDATED. I CURRENT restano invariati; i file esclusivamente locali restano locali.","Local library information loading…":"Caricamento informazioni libreria locale…","A ready local Node host, a supported installed Chromium browser and compatible Canvas/WebGL support are required.":"Servono l’host Node locale pronto, un browser Chromium compatibile e il supporto Canvas/WebGL.","In the 0.1.5.0 reference build, the control labelled Time Gate is an":"Nella build 0.1.5.0 il controllo Time Gate è una",", not a minimum contact duration. This naming is scheduled for revision.":", non una durata minima del contatto. Il nome sarà rivisto.","The native dial shows the Live-owned control and Live’s external modulation. The black field shows the final value sent to the tool, including INDEX MIDI, clamped and quantized to the manifest range. With INDEX MIDI assigned that field is grey; it can differ from the dial. No custom MIDI arc is painted over Live’s native display.":"Il dial nativo mostra il parametro gestito da Live e la modulazione esterna. Il campo nero mostra il valore effettivo inviato al tool, incluso INDEX MIDI, limitato e quantizzato secondo il manifest. Con INDEX MIDI assegnato, il campo diventa grigio e può differire dal dial. Nessun arco MIDI personalizzato viene sovrapposto al display nativo di Live.","The base Live parameter remains the automation/modulation target. MAP ABS and MAP % are the external Live modulator’s mapping/range modes. Choose them in the modulator; INDEX receives its native parameter output. INDEX does not reinterpret either mode or write the effective MIDI result back into the parameter. ABS ↔ % visual behavior in this candidate still requires native Max/Live testing.":"Il parametro Live di base rimane la destinazione di automazione/modulazione. MAP ABS e MAP % sono modalità di mappatura/intervallo del modulatore esterno di Live: sceglile nel modulatore, mentre INDEX riceve il risultato del parametro nativo. INDEX non reinterpreta le modalità e non riscrive nel parametro il risultato MIDI effettivo. Il comportamento visivo ABS ↔ % richiede ancora test nativi Max/Live.","Mappings start unassigned. Choose the MIDI input and channel, then a slot source and NOTE/CC ID. NONE unassigns a slot. Amount sets the contribution; attack/release shape its response. Assignments are Layer-specific and saved with the Set; the functional Live controls keep their automation identities.":"Le mappature sono inizialmente vuote. Scegli ingresso e canale MIDI, sorgente dello slot e ID NOTE/CC. NONE rimuove l’assegnazione. Amount regola il contributo, Attack/Release la risposta. Ogni assegnazione è specifica del Layer e viene salvata con il Set; i controlli Live mantengono le identità di automazione.","RENDER launches the localhost compositor in an external Chromium app window. Live state reaches one compositor SSE connection, then the five tool iframes through":"RENDER avvia il compositore localhost in una finestra app Chromium esterna. Lo stato Live raggiunge una singola connessione SSE del compositore, poi i cinque iframe tramite","Actual / target FPS shows completed visual frames. The display-only dial fills up to the target and cannot be edited. FRAME CADENCE reports the observed interval between completed frames in milliseconds, not GPU execution time. PREVIEW shows the effective buffer dimensions.":"Actual / target FPS mostra i frame visual effettivamente completati. Il dial, solo indicatore, si riempie fino al target e non è modificabile. FRAME CADENCE indica in millisecondi l’intervallo osservato tra frame completati, non il tempo di esecuzione GPU. PREVIEW mostra le dimensioni reali del buffer.","AUTO follows browser / display-driven cadence; its target is estimated (~). Fixed settings request a maximum of 30 or 60 FPS across the hosted tools and compositor. Actual FPS can be lower with heavier tools.":"AUTO segue la cadenza del browser/display; il target è stimato (~). Le impostazioni fisse richiedono un massimo di 30 o 60 FPS per tool e compositore. I frame reali possono diminuire con tool più pesanti.","AUTO keeps window-dependent rendering. Fixed presets control pixel workload: 1280 × 720, 1920 × 1080, 2560 × 1440 or 3840 × 2160 in a 16:9 window. Other window shapes keep their framing and fill the window, using a buffer that fits within the preset dimensions. PREVIEW reports the actual size; Retina does not multiply a fixed preset.":"AUTO mantiene il rendering dipendente dalla finestra. I preset fissi limitano il carico pixel a 1280 × 720, 1920 × 1080, 2560 × 1440 o 3840 × 2160 in una finestra 16:9. Formati diversi mantengono l’inquadratura e riempiono la finestra usando un buffer entro le dimensioni del preset. PREVIEW indica la dimensione effettiva; Retina non moltiplica un preset fisso.","The full composition scales to the RENDER window without zooming or cropping when RES changes. Settings survive closing and reopening RENDER and are saved with the Live Set. A new unconfigured device starts from AUTO / AUTO. If a buffer is unsupported, INDEX reports the error and restores the preceding selection.":"La composizione si adatta alla finestra RENDER senza zoom o ritaglio quando RES cambia. Le impostazioni persistono dopo chiusura e riapertura di RENDER e sono salvate col Live Set. Un device nuovo parte da AUTO / AUTO. Se il buffer non è supportato, INDEX segnala l’errore e ripristina la selezione precedente.","Completed videos appear directly in":"I video completati si trovano direttamente in","if Live cannot provide a saved Set name. Collisions add _02, _03…; existing files are never overwritten. Active work stays in":"se Live non può fornire il nome di un Set salvato. In caso di collisione si aggiungono _02, _03…; i file esistenti non vengono sovrascritti. I lavori attivi restano in",". Reports stay in":". I report rimangono in","; they may contain local paths, tool names and project information. The Bridge never sweeps old jobs or reports.":"; possono contenere percorsi locali, nomi dei tool e informazioni sul progetto. Il Bridge non cancella automaticamente vecchi job o report.","; the finalizer trims and validates a separate":"; il finalizer ritaglia e verifica un file separato","when the complete range passes.":"quando l’intero intervallo supera la verifica.","Loading current audio status…":"Caricamento stato audio corrente…","If macOS blocks a trusted, verified executable because its developer cannot be verified, follow":"Si macOS blocca un eseguibile affidabile e verificato perché non ne riconosce lo sviluppatore, segui","macOS security: opening blocked applications":"sicurezza macOS: apertura di applicazioni bloccate","Keep the complete folder together, load a local tool, and confirm Chromium is installed. RENDER opens an isolated app-style Chromium window; HELP uses the normal browser. Missing tool/module/font errors need the exact Console message and package version. CHECK refreshes metadata without replacing HTML; UPDATE explicitly downloads a selected tool.":"Mantieni completa la cartella, carica un tool locale e verifica che Chromium sia installato. RENDER apre una finestra Chromium isolata, HELP il browser normale. Per errori di tool, moduli o font mancanti servono il messaggio esatto della Console e la versione del pacchetto. CHECK aggiorna i metadati senza sostituire l’HTML; UPDATE scarica esplicitamente il tool selezionato.","SERIOUSLY MADE FOR FUN.":"FATTI SERIAMENTE PER DIVERTIRSI.","Your language preference is stored in your browser when supported. A language code may also appear in page URLs to keep it while navigating. B4~M4L does not use this preference for profiling.":"La preferenza linguistica viene salvata nel browser, quando possibile. Un codice lingua può comparire anche nell’URL per mantenerla navigando. B4~M4L non utilizza questa preferenza per profilazione.","Perform live":"Performance live","The permanent strip: project, HELP, live output and five Layers.":"La barra sempre visibile: progetto, HELP, uscita live e cinque livelli.","One dedicated live Chromium output for each Bridge instance.":"Un’uscita Chromium live dedicata per ogni istanza di Bridge.","Monitor completed live frames and choose the rendering workload.":"Controlla i frame live completati e scegli il carico di rendering.","Relate the final audio and time signals through a third independent carrier.":"Metti in relazione i segnali finali audio e tempo con un terzo segnale di modulazione indipendente.","Behaviours":"Comportamenti","MIXED":"MIXED"},"de":{"MAX FOR LIVE DEVICES.":"MAX-FOR-LIVE-DEVICES.","DOCUMENTATION, CHANGELOGS AND EVERYTHING YOU NEED TO KNOW. WITHOUT THE FLUFF.":"DOKUMENTATION, CHANGELOGS UND ALLES WISSENSWERTE. OHNE SCHNICKSCHNACK.","Explore the device":"Device entdecken","CORE IMAGE PENDING":"CORE-ANSICHT FOLGT","CORE SCREENSHOT / PENDING":"CORE-SCREENSHOT / FOLGT","Testing · Staging · Not distributed":"Testphase · Staging · Nicht veröffentlicht","TESTING · STAGING · NOT DISTRIBUTED":"TESTPHASE · STAGING · NICHT VERÖFFENTLICHT","Two distinct modulation signals from audio: one follows the moment, the other follows the time it lasts.":"Zwei unterschiedliche Modulationssignale aus Audio: eines folgt dem Moment, das andere dessen Dauer.","← ALL DEVICES":"← ALLE DEVICES","PRIVACY":"DATENSCHUTZ","HELP":"HILFE","Quick":"Start","Quick start":"Schnellstart","Trouble":"Probleme","Troubleshooting":"Fehlerbehebung","Under":"Technik","Under the hood":"Unter der Haube","Layers":"Ebenen","Params":"Parameter","Parameters":"Parameter","Color":"Farbe","Library":"Bibliothek","Performance":"Leistung","Main":"Hauptansicht","Time":"Zeit","Behaviors":"Verhaltensweisen","Mapping":"Zuordnung","01 / REQUIREMENTS":"01 / ANFORDERUNGEN","COMPATIBILITY":"KOMPATIBILITÄT","02 / VERSION HISTORY":"02 / VERSIONSVERLAUF","03 / DOCUMENTATION":"03 / DOKUMENTATION","HELP & GUIDES ↓":"HILFE & HANDBÜCHER ↓","CHANGELOG":"ÄNDERUNGSPROTOKOLL","PUBLIC RELEASE NOTES":"ÖFFENTLICHE VERSIONSHINWEISE","REPORT AN ISSUE":"PROBLEM MELDEN","Report an issue or get in touch.":"Ein Problem melden oder Kontakt aufnehmen.","Having trouble with INDEX HTML BRIDGE? Get in touch.":"Probleme mit INDEX HTML BRIDGE? Melde dich.","Having trouble with CONSEQUENCE OF TIME? Get in touch.":"Probleme mit CONSEQUENCE OF TIME? Melde dich.","DEVICE SCREENSHOT / PENDING":"DEVICE-SCREENSHOT / FOLGT","MAXFORLIVE PROFILE":"MAXFORLIVE-PROFIL","TEST ENVIRONMENT":"TESTUMGEBUNG","PLATFORM":"PLATTFORM","DISTRIBUTION":"VERTRIEB","RUNTIME":"LAUFZEIT","Not yet cleared":"Noch nicht freigegeben","Two independent modulation signals from one audio input: A follows intensity, B grows with recognized contact time. Shape both in Ableton Live.":"Zwei unabhängige Modulationssignale aus einem Audioeingang: A folgt der Intensität, B wächst mit der erkannten Kontaktdauer. Beide in Ableton Live formen.","Established development target; exact minimum release version is not certified.":"Entwicklungsziel; die genaue Mindestversion ist noch nicht zertifiziert.","Intel and Apple Silicon environments have been used in development. This candidate still requires acceptance. Windows untested.":"Entwicklungstests auf Intel- und Apple-Silicon-Macs; die Kandidatenversion wartet auf Abnahme. Windows wurde nicht getestet.","0.1.5.0 tested partially with Live 12.4.2 and bundled Max 9.1.4. These are not certified minimum requirements.":"0.1.5.0 teilweise mit Live 12.4.2 und Max 9.1.4 getestet. Dies sind keine zertifizierten Mindestanforderungen.","macOS development testing":"macOS-Entwicklungstests","Apple Silicon tests on 0.1.5.0 are partial. Separate Intel tests apply to 0.1.4.3, not this candidate. Windows untested.":"Apple-Silicon-Tests für 0.1.5.0 sind unvollständig. Die separaten Intel-Tests gelten für 0.1.4.3, nicht für diese Version. Windows ungetestet.","Packaging, portability and redistribution requirements remain unresolved. No public release is being offered here.":"Paketierung, Portabilität und Weiterverteilung sind noch ungeklärt. Hier wird keine öffentliche Version angeboten.","No publicly distributed release has been verified for this documentation snapshot. The manual below references the":"Für diese Dokumentation ist keine öffentliche Version bestätigt. Das folgende Handbuch bezieht sich auf","0.23.9-rc.3 testing candidate":"Testkandidaten 0.23.9-rc.3","; release candidate notes are not published as commercial release history.":"; Hinweise zu Release-Kandidaten erscheinen nicht als Verlauf kommerzieller Versionen.","No public release is currently confirmed. This documentation is a":"Es ist noch keine öffentliche Version bestätigt. Diese Dokumentation ist ein","draft based on testing candidate 0.1.5.0":"Entwurf zur Testversion 0.1.5.0","; internal milestones are deliberately excluded from public release notes.":"; interne Meilensteine sind bewusst nicht in öffentlichen Versionshinweisen enthalten.","Documentation draft — review before first public release.":"Dokumentationsentwurf – vor Veröffentlichung prüfen.","EXTERNAL SERVICES":"EXTERNE DIENSTE","LANGUAGE PREFERENCE":"SPRACHPRÄFERENZ","SUPPORT EMAIL":"SUPPORT-E-MAIL","CONTROLLER / CONTACT":"VERANTWORTLICHER / KONTAKT","B4~M4L is a static documentation website. The current site code contains no first-party analytics, advertising pixels, forms or user accounts.":"B4~M4L ist eine statische Dokumentationswebsite. Der aktuelle Code enthält keine eigenen Analysen, Werbepixel, Formulare oder Nutzerkonten.","The site is intended to be hosted with GitHub Pages. GitHub may process visitor data, including IP addresses, under its own privacy statement.":"Die Website wird voraussichtlich über GitHub Pages gehostet. GitHub kann Besucherdaten einschließlich IP-Adressen gemäß seiner Datenschutzerklärung verarbeiten.","GitHub Privacy Statement":"GitHub-Datenschutzerklärung","The REPORT AN ISSUE button opens your email application using a prefilled message. B4~M4L does not automatically transmit attachments or diagnostics. Any information you choose to send by email is handled through the email services involved.":"Die Schaltfläche PROBLEM MELDEN öffnet das E-Mail-Programm mit einem vorausgefüllten Text. B4~M4L sendet keine Anhänge oder Diagnosedaten automatisch. Freiwillige E-Mails werden durch die beteiligten Dienste verarbeitet.","Development reference only · final installation workflow to be verified on the distributed build.":"Nur Entwicklungsreferenz: Installation muss noch an der späteren Distributionsversion geprüft werden.","Send some audio":"Audiosignal zuführen","Load COT onto an audio track in Live, or select an external sidechain source.":"COT auf einer Audiospur in Live laden oder eine externe Sidechain-Quelle wählen.","Watch A and B":"A und B beobachten","A follows current intensity. B develops while contact is recognized.":"A folgt der aktuellen Intensität. B entwickelt sich, solange Kontakt erkannt wird.","Shape the signals":"Signale formen","Use AUDIO to set A response. Use TIME for Window, Growth, Accel and B Attack/Hold/Decay.":"AUDIO bestimmt die Reaktion von A, TIME steuert Window, Growth, Accel sowie Attack/Hold/Decay von B.","Map two destinations":"Zwei Ziele zuweisen","Assign A and B separately in Live, and compare Mod with Remote behavior.":"A und B in Live separat zuordnen und Mod mit Remote vergleichen.","Try behaviors":"Verhaltensweisen testen","Start in CLEAN, then explore the seven other modes and their Time Amount controls.":"Mit CLEAN beginnen, danach die sieben weiteren Modi und ihre Time-Amount-Regler testen.","Two independent modulation signals, one shared audio input.":"Zwei unabhängige Modulationssignale, ein gemeinsamer Audioeingang.","A / Audio Signal":"A / Audiosignal","B / Time Signal":"B / Zeitsignal","Tracks audio intensity via an envelope follower. A ranges from 0 to 1 and responds relatively quickly to changes in the source.":"Verfolgt die Audiointensität mit einem Envelope Follower. A liegt zwischen 0 und 1 und reagiert relativ schnell auf Änderungen.","Accumulates recognized contact time. B also ranges from 0 to 1, but follows its own time engine, hold and decay.":"Summiert die erkannte Kontaktdauer. Auch B liegt zwischen 0 und 1, folgt aber einer eigenen Zeitlogik mit Hold und Decay.","The scope":"Die Anzeige","The two traces represent separate signals; they are not combined. MIXED / Output C is not implemented in the documented testing build.":"Die beiden Kurven zeigen getrennte Signale und werden nicht zusammengeführt. MIXED / Output C ist in dieser Testversion nicht implementiert.","Shape the audio-responsive signal A.":"Das auf Audio reagierende Signal A formen.","Audio source":"Audioquelle","Use the main track input or select an external sidechain. Check routing when nothing moves.":"Haupteingang der Spur oder externe Sidechain verwenden. Falls sich nichts bewegt, Routing prüfen.","Adjust incoming level before the signal is analyzed.":"Den Eingangspegel vor der Analyse anpassen.","Set how quickly signal A reacts to increasing and decreasing audio intensity. These controls do not modify B Attack, Hold or Decay.":"Bestimmt, wie schnell A auf steigende oder fallende Audiointensität reagiert. B Attack, Hold und Decay bleiben unverändert.","Adjust the amount applied to normalized A. It is not the contact threshold used by the time engine.":"Bestimmt die Stärke des normierten Signals A. Dies ist nicht die Kontaktschwelle der Zeitlogik.","Build a time-driven signal B from recognized contact.":"Ein zeitgesteuertes Signal B aus erkanntem Kontakt erzeugen.","Contact threshold":"Kontaktschwelle","audio-intensity threshold (%)":"Audiointensitätsschwelle (%)","Allows short gaps beneath the threshold without immediately ending contact. After contact really ends, B proceeds to Hold and then Decay.":"Kurze Lücken unter der Schwelle beenden den Kontakt nicht sofort. Endet der Kontakt wirklich, folgt B zunächst Hold und dann Decay.","Choose BEATS (musical tempo) or TIME (elapsed time) as the accumulation window; the two modes retain separate values.":"BEATS (musikalisches Tempo) oder TIME (verstrichene Zeit) als Akkumulationsfenster wählen; beide Modi speichern getrennte Werte.","Growth changes accumulation rate. Negative Accel gradually slows forward progress without reversing time. The reference build uses an Accel range of −4…+4.":"Growth verändert die Akkumulationsrate. Negatives Accel bremst den Fortschritt schrittweise, ohne die Zeit umzukehren. Accel reicht in dieser Version von −4 bis +4.","Set initial signal level and range of movement.":"Startpegel und Bewegungsbereich des Signals festlegen.","Attack smooths growth, Hold keeps the value after contact is lost, Decay returns B toward zero.":"Attack glättet den Anstieg, Hold hält den Wert nach Kontaktverlust und Decay führt B gegen null zurück.","Eight ways to reshape B over time.":"Acht Wege, B im Zeitverlauf zu formen.","Pure time evolution. Time Amount has no effect in CLEAN.":"Reiner Zeitverlauf. Time Amount hat in CLEAN keinen Effekt.","Changes movement range in response to intensity.":"Verändert den Bewegungsbereich je nach Intensität.","Changes accumulation speed in response to intensity.":"Verändert die Akkumulationsgeschwindigkeit je nach Intensität.","Adds signal-dependent irregular fluctuations.":"Fügt signalabhängige unregelmäßige Schwankungen hinzu.","May produce a descending positive curve, not negative output; transitions can be abrupt.":"Kann eine abfallende positive Kurve erzeugen, aber keinen negativen Ausgang; Übergänge können abrupt sein.","Can pause time progress when intensity meets its condition.":"Kann den Zeitfortschritt anhalten, wenn die Intensitätsbedingung erfüllt ist.","Quantizes the time signal into discrete steps.":"Quantisiert das Zeitsignal in einzelne Stufen.","Combines speed changes and irregular fluctuations. Time Amount adjusts each active behavior, not the basic B Depth.":"Kombiniert Geschwindigkeitsänderungen und unregelmäßige Schwankungen. Time Amount steuert den jeweiligen Effekt, nicht die grundlegende B Depth.","Connect A and B to separate Live destinations.":"A und B mit getrennten Live-Zielen verbinden.","A and B mapping":"A-/B-Zuordnung","Map A and B independently to parameters in Ableton Live using the device mapping controls.":"A und B mit den Zuordnungsreglern des Devices unabhängig auf Live-Parameter legen.","Mod works as relative modulation around a parameter base value. Remote takes exclusive control of its destination. These are native Ableton behaviors.":"Mod moduliert relativ zum Basiswert eines Parameters. Remote übernimmt die alleinige Kontrolle des Ziels. Beides ist natives Ableton-Verhalten.","Save & Reload":"Speichern & neu laden","After mapping, verify actual modulation after saving and reopening the Live Set — not only that the destination name persists.":"Nach dem Zuordnen den Live Set speichern und erneut öffnen; prüfen, ob die Modulation wirklich arbeitet, nicht nur der Zielname erhalten bleibt.","Distribution note":"Hinweis zur Distribution","The referenced testing build uses native Ableton mapping abstractions with unresolved distribution/portability requirements. Do not use it as an installation guide for a public release.":"Diese Testversion verwendet native Ableton-Mapping-Abstraktionen mit ungeklärten Verteilungs- und Portabilitätsanforderungen. Sie ist keine Installationsanleitung für eine öffentliche Version.","Choose a separate source for audio analysis.":"Eine separate Quelle für die Audioanalyse wählen.","Main audio":"Hauptaudio","External sidechain":"Externe Sidechain","Choose an appropriate external source in Live, confirm routing, then watch the two traces in MAIN.":"In Live eine externe Quelle wählen, das Routing prüfen und die beiden Kurven in MAIN beobachten.","Reference layout":"Referenzlayout","The sidechain panel appears to the right in 0.1.5.0. Its planned relocation is not reflected in this guide.":"In 0.1.5.0 erscheint das Sidechain-Panel rechts. Seine geplante Verlagerung ist hier noch nicht berücksichtigt.","Common checks for signal, timing and mapping.":"Häufige Prüfungen für Signal, Timing und Zuordnung.","No signal movement":"Keine Signalbewegung","Confirm that audio is present, inspect source and routing, increase Gain as appropriate, and check the contact threshold and B Depth.":"Audioeingang, Quelle und Routing prüfen, Gain bei Bedarf erhöhen sowie Kontaktschwelle und B Depth prüfen.","A moves but B does not":"A bewegt sich, B nicht","Check the threshold and Tolerance, the Window, Growth, B Start/Depth and whether sufficient contact time has accumulated.":"Schwelle, Tolerance, Window, Growth und B Start/Depth prüfen sowie die akkumulierte Kontaktdauer kontrollieren.","Mapping looks static":"Zuordnung scheint statisch","In Mod mode, the base knob may stay at its set value while modulation operates. Check the destination response, not only the knob position.":"Im Mod-Modus kann der Basisregler unverändert bleiben, obwohl die Modulation arbeitet. Prüfe das Zielverhalten statt nur die Reglerposition.","Migration to another Mac":"Wechsel auf einen anderen Mac","Portability has not been cleared for 0.1.5.0. Do not treat the development patch as an installer or redistribution package.":"Die Portabilität von 0.1.5.0 ist noch nicht freigegeben. Die Entwicklungspatch ist kein Installer oder Verteilungspaket.","How the two modulation signals differ.":"Unterschiede zwischen den beiden Modulationssignalen.","A: amplitude response":"A: Amplitudenreaktion","The envelope follower translates the level of the input signal into a continuous normalized modulation output.":"Der Envelope Follower wandelt den Eingangspegel in ein kontinuierliches, normiertes Modulationssignal um.","B: duration response":"B: Dauerreaktion","Contact recognition drives a separate time engine. Window, Growth, Accel, Hold, Decay and Behavior change the shape of B.":"Die Kontakterkennung steuert eine eigene Zeitlogik. Window, Growth, Accel, Hold, Decay und Behavior formen B.","No Output C yet":"Noch kein Output C","MAIN displays separate A and B traces. A blended third modulation signal is a future idea, not a current feature.":"MAIN zeigt getrennte A- und B-Kurven. Ein drittes kombiniertes Modulationssignal ist geplant, aber noch nicht verfügbar.","Audio transparency":"Audiotransparenz","Help manifest unavailable.":"HELP-Manifest nicht verfügbar.","Open this page through the B4~M4L local server or check that the documentation manifest is present.":"Seite über den lokalen B4~M4L-Server öffnen oder prüfen, ob das Dokumentationsmanifest vorhanden ist.","Pick a layer":"Ebene wählen","Open L1–L5. Only one Layer editor is open at a time.":"L1–L5 öffnen. Es kann immer nur ein Layer-Editor gleichzeitig geöffnet sein.","Choose a tool":"Tool wählen","Select it from the library, check its status, then LOAD / UPDATE / DOWNLOAD explicitly.":"Tool aus der Bibliothek wählen, Status prüfen und LOAD / UPDATE / DOWNLOAD ausdrücklich auslösen.","Shape it":"Gestalten","Open PARAMETERS, COLORS & BLEND and MIDI MAPPING in any combination.":"PARAMETERS, COLORS & BLEND und MIDI MAPPING beliebig kombinieren.","Render live":"Live rendern","RENDER opens the external Chromium compositor. Your five Layers are combined there.":"RENDER öffnet den externen Chromium-Compositor, der die fünf Ebenen zusammensetzt.","Five independent visual slots, composed from L1 upward. Effects process only what sits below them.":"Fünf unabhängige visuelle Ebenen ab L1; Effekte bearbeiten nur die darunterliegenden Ebenen.","One editor, five layers":"Ein Editor, fünf Ebenen","Tool loading":"Tool laden","Generator vs effect":"Generator oder Effekt","Remembered per layer":"Pro Ebene gespeichert","Native Live parameters":"Native Live-Parameter","Reset & defaults":"Zurücksetzen & Standardwerte","Effective values":"Effektive Werte","Automation stays yours":"Automation bleibt erhalten","Colors & Blend":"Farben & Blend","Effect Layers do not use generator blend in the same way: their shader processes the lower composite directly.":"Effekte nutzen den Generator-Blend nicht auf dieselbe Weise: Ihr Shader verarbeitet direkt die unteren Ebenen.","MIDI Mapping":"MIDI-Zuordnung","Map NOTE or CC directly onto P01–P12 with amount and envelope/smoothing controls.":"NOTE oder CC direkt auf P01–P12 zuordnen, mit Stärke und Hüllkurven-/Glättungsreglern.","CHECK INDEX compares your local HTML tools with the INDEX catalogue. Nothing updates by itself.":"CHECK INDEX vergleicht lokale HTML-Tools mit dem INDEX-Katalog. Nichts wird automatisch aktualisiert.","Selected tool":"Ausgewähltes Tool","Requirements":"Anforderungen","Live output":"Live-Ausgabe","Live Render Performance":"Leistung beim Live-Rendering","Automatic panel":"Automatisches Panel","Read the monitor":"Monitor lesen","Same view, different quality":"Gleiche Ansicht, andere Qualität","1 · Acquire":"1 · Aufnahme","2 · Replay":"2 · Wiedergabe","3 · Encode":"3 · Kodierung","Current build note":"Hinweis zur aktuellen Version","Files and diagnostic reports":"Dateien und Diagnoseberichte","Current output options":"Aktuelle Ausgabeoptionen","Second pass":"Zweiter Durchlauf","Files":"Dateien","Video audio":"Video-Audio","Testing status":"Teststatus","The useful failure boundaries, current limitations and what not to expect from this build.":"Wichtige Fehlergrenzen, aktuelle Einschränkungen und was diese Version nicht leistet.","macOS security":"macOS-Sicherheit","Clock and incomplete range":"Clock und unvollständiger Bereich","No final file / incomplete cleanup":"Keine finale Datei / unvollständiges Aufräumen","Browser or missing resources":"Browser oder fehlende Ressourcen","Current limitations":"Aktuelle Einschränkungen","Only if you care: how Max, Node and Chromium divide the work.":"Für Interessierte: So teilen Max, Node und Chromium die Arbeit auf.","No Jitter renderer":"Kein Jitter-Renderer","INDEX HTML stays browser-native. The fundamental split is simple: Max decides what happens; the browser decides how to draw it.":"INDEX HTML bleibt browsernativ: Max entscheidet, was geschieht; der Browser entscheidet, wie es dargestellt wird.","Links to":"Links zu","and third-party websites open independent services. Their own privacy policies apply when you visit them. If you follow a link to Apple, see the":"und anderen Websites führen zu unabhängigen Diensten. Dort gelten deren Datenschutzhinweise. Für Links zu Apple siehe die","Apple Privacy Policy":"Apple-Datenschutzerklärung","Matteo Belgiovine — Turin, Italy ·":"Matteo Belgiovine — Turin, Italien ·","Open one Layer editor at a time. Layer visibility is independent from whether its editor is open.":"Immer nur einen Layer-Editor öffnen. Die Sichtbarkeit einer Ebene hängt nicht vom geöffneten Editor ab.","Choosing a tool in the dropdown only selects it. Press LOAD to use the selection. A new LOAD restores manifest defaults. Keep tools/ and the complete device folder together; local INDEX_TOOL RC2 and legacy SKETCH_TOOL files work offline.":"Die Auswahl im Dropdown lädt das Tool nicht. Mit LOAD wird es gestartet; erneutes LOAD stellt Manifest-Defaults wieder her. tools/ und Device-Ordner zusammenhalten; INDEX_TOOL RC2 und ältere SKETCH_TOOL-Dateien funktionieren offline.","Generators draw their own canvas. Effects receive the composite of the Layers beneath them and process that result.":"Generatoren zeichnen auf ihre eigene Canvas. Effekte verarbeiten die Kombination der darunterliegenden Ebenen.","Each Layer remembers its section visibility. Saving a Live Set also stores the loaded tools, native values, HEX, mappings and device settings. Changing a tool resets its values: there is no separate preset memory for every tool. Keep the local tool files available when reopening a Set.":"Jede Ebene merkt sich geöffnete Bereiche. Live Sets speichern geladene Tools, native Werte, HEX-Farben, Mappings und Einstellungen. Beim Toolwechsel werden Werte zurückgesetzt; es gibt keinen eigenen Preset-Speicher je Tool. Lokale Tool-Dateien beim erneuten Öffnen bereithalten.","Twelve numeric slots per Layer, mapped to each tool’s own manifest labels and ranges.":"Zwölf numerische Slots pro Ebene, deren Namen und Bereiche das jeweilige Tool-Manifest vorgibt.","The device exposes a stable Live parameter registry for automation and external modulation.":"Das Device stellt eine stabile Liste von Live-Parametern für Automation und externe Modulation bereit.","Use the single reset beside a parameter for that control only. DEFAULT restores the loaded tool’s manifest defaults.":"Der Reset neben einem Parameter betrifft nur diesen Regler. DEFAULT stellt die Standardwerte des geladenen Tools wieder her.","Up to four tool-defined colors, independent opacity and per-Layer blend mode.":"Bis zu vier tooldefinierte Farben mit eigener Deckkraft und einem Blend-Modus pro Ebene.","Each active color can be edited with the picker or six-digit HEX input. Unused manifest slots stay clearly marked.":"Aktive Farben lassen sich per Farbwähler oder sechsstelligen HEX-Wert bearbeiten. Unbenutzte Slots sind gekennzeichnet.","Color opacity is a native host control and does not consume P01–P12. Missing host opacity keeps the standalone tool behaviour unchanged.":"Deckkraft ist eine native Host-Steuerung und belegt keinen Slot P01–P12. Ohne Host-Deckkraft bleibt das Standalone-Verhalten gleich.","Velocity becomes the modulation peak. Attack rises to that peak, then release returns automatically to zero.":"Velocity bestimmt die Modulationsspitze. Attack steigt dorthin, Release fällt automatisch auf null zurück.","The incoming 0–127 value becomes the target. Attack smooths upward movement; release smooths downward movement.":"Der eingehende CC-Wert von 0 bis 127 wird zum Ziel. Attack glättet Aufwärtsbewegungen, Release Abwärtsbewegungen.","Refreshes the remote catalogue and compares it with the flat local":"Aktualisiert den Remote-Katalog und vergleicht ihn mit der lokalen","library. It does not download tools automatically.":"Bibliothek. Tools werden nicht automatisch heruntergeladen.","Depending on state, the action becomes LOAD, UPDATE or DOWNLOAD. A dropdown selection alone never changes the running Layer.":"Je nach Zustand heißt die Aktion LOAD, UPDATE oder DOWNLOAD. Eine Dropdown-Auswahl allein ändert die laufende Ebene nie.","Queues only MISSING and OUTDATED catalogue tools. CURRENT entries are left untouched; local-only fixtures remain local.":"Nimmt nur MISSING- und OUTDATED-Tools in die Warteschlange. CURRENT bleibt unberührt; rein lokale Dateien bleiben lokal.","Local library information loading…":"Lokale Bibliothek wird geladen…","A ready local Node host, a supported installed Chromium browser and compatible Canvas/WebGL support are required.":"Ein laufender lokaler Node-Host, ein unterstützter Chromium-Browser sowie Canvas/WebGL-Unterstützung sind erforderlich.","In the 0.1.5.0 reference build, the control labelled Time Gate is an":"In der Referenzversion 0.1.5.0 ist der Regler Time Gate eine",", not a minimum contact duration. This naming is scheduled for revision.":", keine Mindestkontaktdauer. Diese Bezeichnung soll überarbeitet werden.","The native dial shows the Live-owned control and Live’s external modulation. The black field shows the final value sent to the tool, including INDEX MIDI, clamped and quantized to the manifest range. With INDEX MIDI assigned that field is grey; it can differ from the dial. No custom MIDI arc is painted over Live’s native display.":"Der native Regler zeigt den von Live verwalteten Parameter samt externer Modulation. Das schwarze Feld zeigt den endgültigen Wert für das Tool, einschließlich INDEX MIDI, auf den Manifestbereich begrenzt und quantisiert. Bei zugewiesenem INDEX MIDI wird das Feld grau und kann vom Regler abweichen. Die native Live-Anzeige erhält keinen zusätzlichen MIDI-Bogen.","The base Live parameter remains the automation/modulation target. MAP ABS and MAP % are the external Live modulator’s mapping/range modes. Choose them in the modulator; INDEX receives its native parameter output. INDEX does not reinterpret either mode or write the effective MIDI result back into the parameter. ABS ↔ % visual behavior in this candidate still requires native Max/Live testing.":"Der Live-Basisparameter bleibt Ziel für Automation und Modulation. MAP ABS und MAP % sind Mapping-/Bereichsmodi des externen Live-Modulators; sie werden dort gewählt. INDEX erhält den nativen Parameterausgang, interpretiert diese Modi nicht neu und schreibt das effektive MIDI-Ergebnis nicht in den Parameter zurück. Das Anzeigeverhalten ABS ↔ % dieser Version muss noch nativ in Max/Live getestet werden.","Mappings start unassigned. Choose the MIDI input and channel, then a slot source and NOTE/CC ID. NONE unassigns a slot. Amount sets the contribution; attack/release shape its response. Assignments are Layer-specific and saved with the Set; the functional Live controls keep their automation identities.":"Mappings beginnen ohne Zuweisung. MIDI-Eingang und Kanal sowie Slot-Quelle und NOTE-/CC-ID wählen. NONE entfernt die Zuweisung. Amount bestimmt den Beitrag, Attack/Release formen die Reaktion. Zuweisungen gelten pro Ebene und werden mit dem Set gespeichert; Live-Steuerungen behalten ihre Automationsidentitäten.","RENDER launches the localhost compositor in an external Chromium app window. Live state reaches one compositor SSE connection, then the five tool iframes through":"RENDER startet den localhost-Compositor in einem externen Chromium-App-Fenster. Der Live-Zustand gelangt über eine SSE-Verbindung zum Compositor und dann zu den fünf Tool-Iframes über","Actual / target FPS shows completed visual frames. The display-only dial fills up to the target and cannot be edited. FRAME CADENCE reports the observed interval between completed frames in milliseconds, not GPU execution time. PREVIEW shows the effective buffer dimensions.":"Actual / target FPS zeigt fertig gerenderte Frames. Der rein anzeigende Regler füllt sich bis zum Zielwert und ist nicht editierbar. FRAME CADENCE misst den Abstand zwischen fertigen Frames in Millisekunden, nicht die GPU-Rechenzeit. PREVIEW zeigt die tatsächlichen Buffermaße.","AUTO follows browser / display-driven cadence; its target is estimated (~). Fixed settings request a maximum of 30 or 60 FPS across the hosted tools and compositor. Actual FPS can be lower with heavier tools.":"AUTO folgt dem Takt von Browser/Display, der Zielwert ist geschätzt (~). Feste Einstellungen begrenzen Tools und Compositor auf höchstens 30 oder 60 FPS. Mit anspruchsvollen Tools können die tatsächlichen FPS sinken.","AUTO keeps window-dependent rendering. Fixed presets control pixel workload: 1280 × 720, 1920 × 1080, 2560 × 1440 or 3840 × 2160 in a 16:9 window. Other window shapes keep their framing and fill the window, using a buffer that fits within the preset dimensions. PREVIEW reports the actual size; Retina does not multiply a fixed preset.":"AUTO passt das Rendering der Fenstergröße an. Feste Presets begrenzen die Pixelarbeit auf 1280 × 720, 1920 × 1080, 2560 × 1440 oder 3840 × 2160 bei 16:9. Andere Fensterformate behalten den Bildausschnitt und füllen das Fenster mit einem Buffer innerhalb der Presetgrenzen. PREVIEW zeigt die tatsächliche Größe; Retina vervielfacht feste Presets nicht.","The full composition scales to the RENDER window without zooming or cropping when RES changes. Settings survive closing and reopening RENDER and are saved with the Live Set. A new unconfigured device starts from AUTO / AUTO. If a buffer is unsupported, INDEX reports the error and restores the preceding selection.":"Die gesamte Komposition wird bei RES-Änderungen ohne Zoom oder Beschnitt ans RENDER-Fenster skaliert. Einstellungen bleiben beim Schließen erhalten und werden im Live Set gespeichert. Neue Devices beginnen mit AUTO / AUTO. Ist ein Buffer nicht unterstützt, meldet INDEX einen Fehler und stellt die vorherige Auswahl wieder her.","Completed videos appear directly in":"Fertige Videos liegen direkt in","if Live cannot provide a saved Set name. Collisions add _02, _03…; existing files are never overwritten. Active work stays in":"falls Live keinen gespeicherten Set-Namen liefert. Bei Namenskonflikten werden _02, _03… ergänzt, bestehende Dateien nie überschrieben. Laufende Jobs bleiben in",". Reports stay in":". Berichte bleiben in","; they may contain local paths, tool names and project information. The Bridge never sweeps old jobs or reports.":"; sie können lokale Pfade, Tool-Namen und Projektdaten enthalten. Der Bridge löscht alte Jobs oder Berichte nie pauschal.","; the finalizer trims and validates a separate":"; der Finalizer schneidet und prüft eine separate","when the complete range passes.":"wenn der vollständige Bereich die Prüfung besteht.","Loading current audio status…":"Aktueller Audiostatus wird geladen…","If macOS blocks a trusted, verified executable because its developer cannot be verified, follow":"Wenn macOS eine vertrauenswürdige, geprüfte ausführbare Datei wegen unbekanntem Entwickler blockiert, siehe","macOS security: opening blocked applications":"macOS-Sicherheit: blockierte Apps öffnen","Keep the complete folder together, load a local tool, and confirm Chromium is installed. RENDER opens an isolated app-style Chromium window; HELP uses the normal browser. Missing tool/module/font errors need the exact Console message and package version. CHECK refreshes metadata without replacing HTML; UPDATE explicitly downloads a selected tool.":"Vollständigen Ordner zusammenhalten, lokales Tool laden und Chromium-Installation prüfen. RENDER öffnet ein isoliertes Chromium-App-Fenster, HELP den normalen Browser. Bei fehlenden Tools/Modulen/Schriften die genaue Console-Meldung und Paketversion notieren. CHECK aktualisiert Metadaten ohne HTML-Ersatz; UPDATE lädt ausgewählte Tools ausdrücklich herunter.","SERIOUSLY MADE FOR FUN.":"MIT ERNST GEMACHT. FÜR DEN SPASS.","Your language preference is stored in your browser when supported. A language code may also appear in page URLs to keep it while navigating. B4~M4L does not use this preference for profiling.":"Die Sprachauswahl wird nach Möglichkeit im Browser gespeichert. Ein Sprachcode kann zusätzlich in Seiten-URLs erscheinen, damit die Auswahl beim Navigieren erhalten bleibt. B4~M4L verwendet diese Angabe nicht zur Profilbildung."},"es":{"MAX FOR LIVE DEVICES.":"DISPOSITIVOS MAX FOR LIVE.","DOCUMENTATION, CHANGELOGS AND EVERYTHING YOU NEED TO KNOW. WITHOUT THE FLUFF.":"DOCUMENTACIÓN, CAMBIOS Y TODO LO QUE NECESITAS SABER. SIN RODEOS.","DEVICES":"DISPOSITIVOS","Explore the device":"Explorar dispositivo","CORE IMAGE PENDING":"IMAGEN CORE PENDIENTE","CORE SCREENSHOT / PENDING":"CAPTURA CORE / PENDIENTE","Testing · Staging · Not distributed":"Pruebas · Staging · No distribuido","TESTING · STAGING · NOT DISTRIBUTED":"PRUEBAS · STAGING · NO DISTRIBUIDO","Two distinct modulation signals from audio: one follows the moment, the other follows the time it lasts.":"Dos señales de modulación desde el audio: una sigue el instante y la otra su duración.","← ALL DEVICES":"← TODOS LOS DISPOSITIVOS","SHOP":"TIENDA","Shop":"Tienda","PRIVACY":"PRIVACIDAD","HELP":"AYUDA","SUPPORT":"SOPORTE","Support":"Soporte","Quick":"Inicio","Quick start":"Inicio rápido","Trouble":"Problemas","Troubleshooting":"Solución de problemas","Under":"Técnico","Under the hood":"Cómo funciona","Layers":"Capas","Params":"Parámetros","Parameters":"Parámetros","Library":"Biblioteca","Performance":"Rendimiento","Main":"Principal","Time":"Tiempo","Behaviors":"Comportamientos","Mapping":"Asignación","Rendering":"Renderizado","01 / REQUIREMENTS":"01 / REQUISITOS","COMPATIBILITY":"COMPATIBILIDAD","02 / VERSION HISTORY":"02 / HISTORIAL DE VERSIONES","03 / DOCUMENTATION":"03 / DOCUMENTACIÓN","HELP & GUIDES ↓":"AYUDA Y GUÍAS ↓","CHANGELOG":"REGISTRO DE CAMBIOS","PUBLIC RELEASE NOTES":"NOTAS DE VERSIÓN PÚBLICAS","REPORT AN ISSUE":"INFORMAR DE UN PROBLEMA","Report an issue or get in touch.":"Informa de un problema o ponte en contacto.","Having trouble with INDEX HTML BRIDGE? Get in touch.":"¿Problemas con INDEX HTML BRIDGE? Escríbeme.","Having trouble with CONSEQUENCE OF TIME? Get in touch.":"¿Problemas con CONSEQUENCE OF TIME? Escríbeme.","DEVICE SCREENSHOT / PENDING":"CAPTURA DEL DISPOSITIVO / PENDIENTE","MAXFORLIVE PROFILE":"PERFIL MAXFORLIVE","TEST ENVIRONMENT":"ENTORNO DE PRUEBA","PLATFORM":"PLATAFORMA","DISTRIBUTION":"DISTRIBUCIÓN","RUNTIME":"EJECUCIÓN","Not yet cleared":"Aún no aprobada","Two independent modulation signals from one audio input: A follows intensity, B grows with recognized contact time. Shape both in Ableton Live.":"Dos señales de modulación independientes desde una entrada de audio: A sigue la intensidad; B crece con la duración detectada del contacto. Ajusta ambas en Ableton Live.","Established development target; exact minimum release version is not certified.":"Entorno de desarrollo de referencia; la versión mínima exacta aún no está certificada.","Intel and Apple Silicon environments have been used in development. This candidate still requires acceptance. Windows untested.":"Se ha desarrollado en Mac Intel y Apple Silicon; esta versión candidata aún debe validarse. Windows no se ha probado.","0.1.5.0 tested partially with Live 12.4.2 and bundled Max 9.1.4. These are not certified minimum requirements.":"0.1.5.0 probado parcialmente con Live 12.4.2 y Max 9.1.4 incluido. No son requisitos mínimos certificados.","macOS development testing":"Pruebas de desarrollo en macOS","Apple Silicon tests on 0.1.5.0 are partial. Separate Intel tests apply to 0.1.4.3, not this candidate. Windows untested.":"Las pruebas en Apple Silicon de 0.1.5.0 son parciales. Las pruebas Intel corresponden a 0.1.4.3, no a esta candidata. Windows sin probar.","Packaging, portability and redistribution requirements remain unresolved. No public release is being offered here.":"El empaquetado, la portabilidad y la redistribución siguen pendientes. Aquí no se ofrece ninguna versión pública.","No publicly distributed release has been verified for this documentation snapshot. The manual below references the":"No hay ninguna versión pública verificada para esta documentación. El manual siguiente corresponde a","0.23.9-rc.3 testing candidate":"versión candidata de prueba 0.23.9-rc.3","; release candidate notes are not published as commercial release history.":"; las notas de versiones candidatas no se presentan como historial comercial.","No public release is currently confirmed. This documentation is a":"No hay una versión pública confirmada. Esta documentación es un","draft based on testing candidate 0.1.5.0":"borrador basado en la versión candidata 0.1.5.0","; internal milestones are deliberately excluded from public release notes.":"; las etapas internas se excluyen deliberadamente de las notas públicas.","Documentation draft — review before first public release.":"Borrador de documentación: revisar antes de publicar.","WEBSITE":"SITIO WEB","HOSTING":"ALOJAMIENTO","EXTERNAL SERVICES":"SERVICIOS EXTERNOS","LANGUAGE PREFERENCE":"PREFERENCIA DE IDIOMA","SUPPORT EMAIL":"CORREO DE SOPORTE","CONTROLLER / CONTACT":"RESPONSABLE / CONTACTO","B4~M4L is a static documentation website. The current site code contains no first-party analytics, advertising pixels, forms or user accounts.":"B4~M4L es un sitio estático de documentación. No incluye análisis propios, píxeles publicitarios, formularios ni cuentas de usuario.","The site is intended to be hosted with GitHub Pages. GitHub may process visitor data, including IP addresses, under its own privacy statement.":"El sitio se alojará en GitHub Pages. GitHub puede tratar datos de visitantes, incluidas direcciones IP, según su política de privacidad.","GitHub Privacy Statement":"Política de privacidad de GitHub","The REPORT AN ISSUE button opens your email application using a prefilled message. B4~M4L does not automatically transmit attachments or diagnostics. Any information you choose to send by email is handled through the email services involved.":"El botón INFORMAR DE UN PROBLEMA abre la aplicación de correo con un mensaje preparado. B4~M4L no envía adjuntos ni diagnósticos automáticamente. La información enviada la tratan los servicios de correo correspondientes.","Development reference only · final installation workflow to be verified on the distributed build.":"Referencia de desarrollo: la instalación definitiva deberá comprobarse con la versión distribuida.","Send some audio":"Envía una señal de audio","Load COT onto an audio track in Live, or select an external sidechain source.":"Carga COT en una pista de audio de Live o selecciona una fuente sidechain externa.","Watch A and B":"Observa A y B","A follows current intensity. B develops while contact is recognized.":"A sigue la intensidad actual. B se desarrolla mientras se detecta contacto.","Shape the signals":"Moldea las señales","Use AUDIO to set A response. Use TIME for Window, Growth, Accel and B Attack/Hold/Decay.":"Usa AUDIO para la respuesta de A y TIME para Window, Growth, Accel y Attack/Hold/Decay de B.","Map two destinations":"Asigna dos destinos","Assign A and B separately in Live, and compare Mod with Remote behavior.":"Asigna A y B por separado en Live y compara Mod con Remote.","Try behaviors":"Prueba los comportamientos","Start in CLEAN, then explore the seven other modes and their Time Amount controls.":"Empieza con CLEAN y explora los otros siete modos y sus controles Time Amount.","Two independent modulation signals, one shared audio input.":"Dos señales de modulación independientes y una entrada de audio compartida.","A / Audio Signal":"A / Señal de audio","B / Time Signal":"B / Señal temporal","Tracks audio intensity via an envelope follower. A ranges from 0 to 1 and responds relatively quickly to changes in the source.":"Sigue la intensidad mediante un seguidor de envolvente. A va de 0 a 1 y responde con relativa rapidez a los cambios.","Accumulates recognized contact time. B also ranges from 0 to 1, but follows its own time engine, hold and decay.":"Acumula el tiempo de contacto detectado. B también va de 0 a 1, pero utiliza su propio motor temporal, hold y decay.","The scope":"La visualización","The two traces represent separate signals; they are not combined. MIXED / Output C is not implemented in the documented testing build.":"Las dos curvas representan señales separadas; no se combinan. MIXED / Output C no está implementado en esta versión de prueba.","Shape the audio-responsive signal A.":"Moldea la señal A sensible al audio.","Audio source":"Fuente de audio","Use the main track input or select an external sidechain. Check routing when nothing moves.":"Usa la entrada de la pista o una sidechain externa. Si no se mueve nada, revisa el enrutamiento.","Adjust incoming level before the signal is analyzed.":"Ajusta el nivel de entrada antes del análisis.","Set how quickly signal A reacts to increasing and decreasing audio intensity. These controls do not modify B Attack, Hold or Decay.":"Ajusta la rapidez con la que A responde a aumentos y descensos de intensidad. No modifica Attack, Hold ni Decay de B.","Adjust the amount applied to normalized A. It is not the contact threshold used by the time engine.":"Ajusta la cantidad aplicada a A normalizada. No es el umbral de contacto del motor temporal.","Build a time-driven signal B from recognized contact.":"Construye una señal temporal B a partir del contacto detectado.","Contact threshold":"Umbral de contacto","audio-intensity threshold (%)":"umbral de intensidad de audio (%)","Allows short gaps beneath the threshold without immediately ending contact. After contact really ends, B proceeds to Hold and then Decay.":"Permite breves pausas bajo el umbral sin terminar inmediatamente el contacto. Al finalizar, B pasa a Hold y luego a Decay.","Choose BEATS (musical tempo) or TIME (elapsed time) as the accumulation window; the two modes retain separate values.":"Elige BEATS (tempo musical) o TIME (tiempo transcurrido) como ventana de acumulación; cada modo conserva sus propios valores.","Growth changes accumulation rate. Negative Accel gradually slows forward progress without reversing time. The reference build uses an Accel range of −4…+4.":"Growth modifica la tasa de acumulación. Accel negativo ralentiza el avance sin invertir el tiempo. El rango de Accel es de −4 a +4.","Set initial signal level and range of movement.":"Define el nivel inicial y el rango de movimiento de la señal.","Attack smooths growth, Hold keeps the value after contact is lost, Decay returns B toward zero.":"Attack suaviza el crecimiento; Hold mantiene el valor tras perder contacto; Decay devuelve B hacia cero.","Eight ways to reshape B over time.":"Ocho maneras de modificar B con el tiempo.","Pure time evolution. Time Amount has no effect in CLEAN.":"Evolución temporal pura. Time Amount no tiene efecto en CLEAN.","Changes movement range in response to intensity.":"Modifica el rango de movimiento según la intensidad.","Changes accumulation speed in response to intensity.":"Modifica la velocidad de acumulación según la intensidad.","Adds signal-dependent irregular fluctuations.":"Añade fluctuaciones irregulares dependientes de la señal.","May produce a descending positive curve, not negative output; transitions can be abrupt.":"Puede generar una curva positiva descendente, no una salida negativa; las transiciones pueden ser bruscas.","Can pause time progress when intensity meets its condition.":"Puede detener el avance del tiempo cuando se cumple la condición de intensidad.","Quantizes the time signal into discrete steps.":"Cuantiza la señal temporal en pasos discretos.","Combines speed changes and irregular fluctuations. Time Amount adjusts each active behavior, not the basic B Depth.":"Combina cambios de velocidad y fluctuaciones irregulares. Time Amount ajusta el efecto activo, no el B Depth básico.","Connect A and B to separate Live destinations.":"Conecta A y B a destinos distintos de Live.","A and B mapping":"Asignación de A y B","Map A and B independently to parameters in Ableton Live using the device mapping controls.":"Asigna A y B por separado a parámetros de Ableton Live con los controles de mapeo del dispositivo.","Mod works as relative modulation around a parameter base value. Remote takes exclusive control of its destination. These are native Ableton behaviors.":"Mod modula de forma relativa al valor base del parámetro. Remote toma el control exclusivo del destino. Son comportamientos nativos de Ableton.","Save & Reload":"Guardar y reabrir","After mapping, verify actual modulation after saving and reopening the Live Set — not only that the destination name persists.":"Después de asignar, guarda y reabre el Live Set para comprobar la modulación real, no solo que persista el nombre del destino.","Distribution note":"Nota sobre distribución","The referenced testing build uses native Ableton mapping abstractions with unresolved distribution/portability requirements. Do not use it as an installation guide for a public release.":"Esta versión usa abstracciones nativas de mapeo de Ableton con requisitos de distribución/portabilidad pendientes. No la utilices como guía de instalación pública.","Choose a separate source for audio analysis.":"Selecciona una fuente aparte para el análisis de audio.","Main audio":"Audio principal","External sidechain":"Sidechain externa","Choose an appropriate external source in Live, confirm routing, then watch the two traces in MAIN.":"Elige una fuente externa en Live, comprueba el enrutamiento y observa las dos curvas en MAIN.","Reference layout":"Diseño de referencia","The sidechain panel appears to the right in 0.1.5.0. Its planned relocation is not reflected in this guide.":"En 0.1.5.0, el panel sidechain aparece a la derecha. Su traslado previsto no se refleja en esta guía.","Common checks for signal, timing and mapping.":"Comprobaciones habituales de señal, tiempo y asignación.","No signal movement":"La señal no se mueve","Confirm that audio is present, inspect source and routing, increase Gain as appropriate, and check the contact threshold and B Depth.":"Comprueba que llega audio, revisa fuente y enrutamiento, aumenta Gain si procede y verifica el umbral y B Depth.","A moves but B does not":"A se mueve pero B no","Check the threshold and Tolerance, the Window, Growth, B Start/Depth and whether sufficient contact time has accumulated.":"Revisa umbral, Tolerance, Window, Growth, B Start/Depth y que se haya acumulado suficiente tiempo de contacto.","Mapping looks static":"La asignación parece estática","In Mod mode, the base knob may stay at its set value while modulation operates. Check the destination response, not only the knob position.":"En modo Mod, el mando base puede permanecer fijo mientras actúa la modulación. Comprueba la respuesta del destino, no solo el mando.","Migration to another Mac":"Migración a otro Mac","Portability has not been cleared for 0.1.5.0. Do not treat the development patch as an installer or redistribution package.":"La portabilidad de 0.1.5.0 no está aprobada. La patch de desarrollo no es un instalador ni un paquete distribuible.","How the two modulation signals differ.":"Cómo se diferencian ambas señales de modulación.","A: amplitude response":"A: respuesta de amplitud","The envelope follower translates the level of the input signal into a continuous normalized modulation output.":"El seguidor de envolvente convierte el nivel de entrada en una modulación continua normalizada.","B: duration response":"B: respuesta de duración","Contact recognition drives a separate time engine. Window, Growth, Accel, Hold, Decay and Behavior change the shape of B.":"La detección de contacto controla un motor temporal aparte. Window, Growth, Accel, Hold, Decay y Behavior modifican B.","No Output C yet":"Output C aún no disponible","MAIN displays separate A and B traces. A blended third modulation signal is a future idea, not a current feature.":"MAIN muestra A y B por separado. Una tercera señal combinada es una idea futura, no una función actual.","Audio transparency":"Transparencia de audio","Help manifest unavailable.":"Manifest HELP no disponible.","Open this page through the B4~M4L local server or check that the documentation manifest is present.":"Abre esta página desde el servidor local de B4~M4L o comprueba que el manifest está presente.","Pick a layer":"Elige una capa","Open L1–L5. Only one Layer editor is open at a time.":"Abre L1–L5. Solo puede abrirse un editor de capa a la vez.","Choose a tool":"Elige una herramienta","Select it from the library, check its status, then LOAD / UPDATE / DOWNLOAD explicitly.":"Elígela en la biblioteca, revisa su estado y pulsa LOAD / UPDATE / DOWNLOAD.","Shape it":"Dale forma","Open PARAMETERS, COLORS & BLEND and MIDI MAPPING in any combination.":"Abre PARAMETERS, COLORS & BLEND y MIDI MAPPING en cualquier combinación.","Render live":"Renderiza en directo","RENDER opens the external Chromium compositor. Your five Layers are combined there.":"RENDER abre el compositor externo Chromium y combina las cinco capas.","Five independent visual slots, composed from L1 upward. Effects process only what sits below them.":"Cinco capas visuales independientes, compuestas desde L1. Los efectos procesan lo que está por debajo.","One editor, five layers":"Un editor, cinco capas","Tool loading":"Carga de herramienta","Generator vs effect":"Generador o efecto","Remembered per layer":"Memoria por capa","Native Live parameters":"Parámetros Live nativos","Reset & defaults":"Restablecer y valores iniciales","Effective values":"Valores efectivos","Automation stays yours":"La automatización sigue intacta","Colors & Blend":"Colores y mezcla","Effect Layers do not use generator blend in the same way: their shader processes the lower composite directly.":"Las capas de efectos no usan la mezcla como los generadores: su shader procesa directamente la composición inferior.","MIDI Mapping":"Mapeo MIDI","Map NOTE or CC directly onto P01–P12 with amount and envelope/smoothing controls.":"Asigna NOTE o CC directamente a P01–P12, con cantidad y controles de envolvente/suavizado.","CHECK INDEX compares your local HTML tools with the INDEX catalogue. Nothing updates by itself.":"CHECK INDEX compara las herramientas HTML locales con el catálogo INDEX. Nada se actualiza automáticamente.","Status":"Estado","Selected tool":"Herramienta seleccionada","Requirements":"Requisitos","Live output":"Salida en directo","Live Render Performance":"Rendimiento del render en directo","Automatic panel":"Panel automático","Read the monitor":"Leer el monitor","Same view, different quality":"Misma vista, distinta calidad","1 · Acquire":"1 · Captura","2 · Replay":"2 · Reproducción","3 · Encode":"3 · Codificación","Current build note":"Nota sobre la versión actual","Files and diagnostic reports":"Archivos e informes de diagnóstico","Current output options":"Opciones de salida actuales","Second pass":"Segunda pasada","Files":"Archivos","Video audio":"Audio del vídeo","Testing status":"Estado de pruebas","The useful failure boundaries, current limitations and what not to expect from this build.":"Límites de fallo útiles, limitaciones actuales y qué no esperar de esta versión.","macOS security":"Seguridad macOS","Clock and incomplete range":"Reloj y rango incompleto","No final file / incomplete cleanup":"Archivo final ausente / limpieza incompleta","Browser or missing resources":"Navegador o recursos ausentes","Current limitations":"Limitaciones actuales","Only if you care: how Max, Node and Chromium divide the work.":"Si quieres profundizar: cómo se reparten el trabajo Max, Node y Chromium.","No Jitter renderer":"Sin renderizador Jitter","INDEX HTML stays browser-native. The fundamental split is simple: Max decides what happens; the browser decides how to draw it.":"INDEX HTML sigue siendo nativo del navegador: Max decide qué ocurre y el navegador cómo dibujarlo.","Links to":"Enlaces a","and third-party websites open independent services. Their own privacy policies apply when you visit them. If you follow a link to Apple, see the":"y otros sitios abren servicios independientes. Al visitarlos se aplican sus políticas de privacidad. Para enlaces a Apple, consulta la","Apple Privacy Policy":"Política de privacidad de Apple","Matteo Belgiovine — Turin, Italy ·":"Matteo Belgiovine — Turín, Italia ·","Open one Layer editor at a time. Layer visibility is independent from whether its editor is open.":"Abre un editor de capa a la vez. Su visibilidad es independiente de que el editor esté abierto.","Choosing a tool in the dropdown only selects it. Press LOAD to use the selection. A new LOAD restores manifest defaults. Keep tools/ and the complete device folder together; local INDEX_TOOL RC2 and legacy SKETCH_TOOL files work offline.":"Elegir una herramienta en el menú solo la selecciona: pulsa LOAD para usarla. Un nuevo LOAD restaura los valores del manifest. Mantén tools/ junto a la carpeta completa del dispositivo; INDEX_TOOL RC2 y SKETCH_TOOL antiguos funcionan offline.","Generators draw their own canvas. Effects receive the composite of the Layers beneath them and process that result.":"Los generadores dibujan en su propio canvas. Los efectos procesan la composición de las capas inferiores.","Each Layer remembers its section visibility. Saving a Live Set also stores the loaded tools, native values, HEX, mappings and device settings. Changing a tool resets its values: there is no separate preset memory for every tool. Keep the local tool files available when reopening a Set.":"Cada capa recuerda sus secciones abiertas. El Live Set guarda herramientas, valores nativos, HEX, asignaciones y ajustes. Cambiar de herramienta restaura sus valores: no hay memoria de presets individual. Conserva los archivos locales al reabrir el Set.","Twelve numeric slots per Layer, mapped to each tool’s own manifest labels and ranges.":"Doce controles numéricos por capa, con nombres y rangos definidos por el manifest de la herramienta.","The device exposes a stable Live parameter registry for automation and external modulation.":"El dispositivo expone un registro estable de parámetros Live para automatización y modulación externa.","Use the single reset beside a parameter for that control only. DEFAULT restores the loaded tool’s manifest defaults.":"El reset junto a un parámetro afecta solo a ese control. DEFAULT restaura los valores por defecto del manifest de la herramienta cargada.","Up to four tool-defined colors, independent opacity and per-Layer blend mode.":"Hasta cuatro colores definidos por la herramienta, opacidad independiente y modo de mezcla por capa.","Each active color can be edited with the picker or six-digit HEX input. Unused manifest slots stay clearly marked.":"Edita los colores activos con el selector o un HEX de seis dígitos. Los espacios no usados permanecen indicados.","Color opacity is a native host control and does not consume P01–P12. Missing host opacity keeps the standalone tool behaviour unchanged.":"La opacidad es un control nativo del host y no ocupa P01–P12. Sin ese control, la herramienta standalone mantiene su comportamiento.","Velocity becomes the modulation peak. Attack rises to that peak, then release returns automatically to zero.":"Velocity establece el pico de modulación. Attack lo alcanza y Release vuelve automáticamente a cero.","The incoming 0–127 value becomes the target. Attack smooths upward movement; release smooths downward movement.":"El valor CC entrante (0–127) es el objetivo. Attack suaviza las subidas y Release las bajadas.","Refreshes the remote catalogue and compares it with the flat local":"Actualiza el catálogo remoto y lo compara con la biblioteca local","library. It does not download tools automatically.":": no descarga herramientas automáticamente.","Depending on state, the action becomes LOAD, UPDATE or DOWNLOAD. A dropdown selection alone never changes the running Layer.":"Según el estado, la acción es LOAD, UPDATE o DOWNLOAD. Elegir en el menú nunca cambia la capa activa por sí solo.","Queues only MISSING and OUTDATED catalogue tools. CURRENT entries are left untouched; local-only fixtures remain local.":"Añade solo herramientas MISSING y OUTDATED. Las CURRENT no cambian; las locales siguen siendo locales.","Local library information loading…":"Cargando información de biblioteca local…","A ready local Node host, a supported installed Chromium browser and compatible Canvas/WebGL support are required.":"Se requiere un host Node local listo, Chromium compatible y soporte Canvas/WebGL.","In the 0.1.5.0 reference build, the control labelled Time Gate is an":"En la versión 0.1.5.0, el control Time Gate es un",", not a minimum contact duration. This naming is scheduled for revision.":", no una duración mínima del contacto. Este nombre se revisará.","The native dial shows the Live-owned control and Live’s external modulation. The black field shows the final value sent to the tool, including INDEX MIDI, clamped and quantized to the manifest range. With INDEX MIDI assigned that field is grey; it can differ from the dial. No custom MIDI arc is painted over Live’s native display.":"El dial nativo muestra el control de Live y su modulación externa. El campo negro indica el valor final enviado a la herramienta, incluido INDEX MIDI, limitado y cuantizado según el manifest. Al asignar INDEX MIDI, el campo se vuelve gris y puede diferir del dial. No se dibuja ningún arco MIDI personalizado sobre el indicador nativo de Live.","The base Live parameter remains the automation/modulation target. MAP ABS and MAP % are the external Live modulator’s mapping/range modes. Choose them in the modulator; INDEX receives its native parameter output. INDEX does not reinterpret either mode or write the effective MIDI result back into the parameter. ABS ↔ % visual behavior in this candidate still requires native Max/Live testing.":"El parámetro base de Live sigue siendo el destino de automatización/modulación. MAP ABS y MAP % son modos de mapeo/rango del modulador externo de Live; selecciónalos en el modulador. INDEX recibe la salida nativa, no reinterpreta esos modos ni escribe el resultado MIDI efectivo en el parámetro. El comportamiento visual ABS ↔ % de esta versión aún requiere pruebas nativas en Max/Live.","Mappings start unassigned. Choose the MIDI input and channel, then a slot source and NOTE/CC ID. NONE unassigns a slot. Amount sets the contribution; attack/release shape its response. Assignments are Layer-specific and saved with the Set; the functional Live controls keep their automation identities.":"Las asignaciones empiezan vacías. Selecciona entrada y canal MIDI, fuente del espacio e ID NOTE/CC. NONE elimina una asignación. Amount determina la intensidad y Attack/Release modelan la respuesta. Cada capa guarda sus asignaciones con el Set; los controles Live conservan sus identidades de automatización.","RENDER launches the localhost compositor in an external Chromium app window. Live state reaches one compositor SSE connection, then the five tool iframes through":"RENDER inicia el compositor localhost en una ventana Chromium externa. El estado de Live llega mediante una conexión SSE al compositor y luego a los cinco iframes por","Actual / target FPS shows completed visual frames. The display-only dial fills up to the target and cannot be edited. FRAME CADENCE reports the observed interval between completed frames in milliseconds, not GPU execution time. PREVIEW shows the effective buffer dimensions.":"Actual / target FPS muestra fotogramas visuales completados. El dial solo indica el valor hasta el objetivo y no se puede editar. FRAME CADENCE mide el intervalo observado entre fotogramas terminados, no el tiempo de GPU. PREVIEW muestra el tamaño real del búfer.","AUTO follows browser / display-driven cadence; its target is estimated (~). Fixed settings request a maximum of 30 or 60 FPS across the hosted tools and compositor. Actual FPS can be lower with heavier tools.":"AUTO sigue la cadencia del navegador/pantalla y su objetivo es estimado (~). Los ajustes fijos solicitan un máximo de 30 o 60 FPS en herramientas y compositor. Los FPS reales pueden ser menores con herramientas exigentes.","AUTO keeps window-dependent rendering. Fixed presets control pixel workload: 1280 × 720, 1920 × 1080, 2560 × 1440 or 3840 × 2160 in a 16:9 window. Other window shapes keep their framing and fill the window, using a buffer that fits within the preset dimensions. PREVIEW reports the actual size; Retina does not multiply a fixed preset.":"AUTO adapta el renderizado a la ventana. Los presets fijos limitan la carga de píxeles a 1280 × 720, 1920 × 1080, 2560 × 1440 o 3840 × 2160 en formato 16:9. Otros formatos conservan el encuadre y llenan la ventana con un búfer dentro del límite del preset. PREVIEW muestra el tamaño real; Retina no multiplica un preset fijo.","The full composition scales to the RENDER window without zooming or cropping when RES changes. Settings survive closing and reopening RENDER and are saved with the Live Set. A new unconfigured device starts from AUTO / AUTO. If a buffer is unsupported, INDEX reports the error and restores the preceding selection.":"La composición se adapta a RENDER sin zoom ni recorte al cambiar RES. Los ajustes se mantienen al cerrar y reabrir RENDER y se guardan con el Live Set. Un dispositivo nuevo empieza en AUTO / AUTO. Si el búfer no es compatible, INDEX avisa y restaura la selección anterior.","Completed videos appear directly in":"Los vídeos terminados aparecen directamente en","if Live cannot provide a saved Set name. Collisions add _02, _03…; existing files are never overwritten. Active work stays in":"si Live no proporciona el nombre de un Set guardado. En caso de coincidencia se añaden _02, _03…; nunca se sobrescriben archivos. Los trabajos activos quedan en",". Reports stay in":". Los informes permanecen en","; they may contain local paths, tool names and project information. The Bridge never sweeps old jobs or reports.":"; pueden incluir rutas locales, nombres de herramientas e información del proyecto. El Bridge no elimina automáticamente trabajos ni informes antiguos.","; the finalizer trims and validates a separate":"; el finalizador recorta y valida un archivo separado","when the complete range passes.":"cuando el rango completo supera la validación.","Loading current audio status…":"Cargando estado actual del audio…","If macOS blocks a trusted, verified executable because its developer cannot be verified, follow":"Si macOS bloquea un ejecutable confiable y verificado porque no reconoce a su desarrollador, sigue","macOS security: opening blocked applications":"seguridad macOS: abrir aplicaciones bloqueadas","Keep the complete folder together, load a local tool, and confirm Chromium is installed. RENDER opens an isolated app-style Chromium window; HELP uses the normal browser. Missing tool/module/font errors need the exact Console message and package version. CHECK refreshes metadata without replacing HTML; UPDATE explicitly downloads a selected tool.":"Mantén junta la carpeta completa, carga una herramienta local y verifica Chromium. RENDER abre una ventana Chromium aislada; HELP usa el navegador normal. Ante errores de herramientas, módulos o fuentes ausentes, guarda el mensaje exacto de consola y versión del paquete. CHECK actualiza metadatos sin sustituir HTML; UPDATE descarga explícitamente la herramienta elegida.","SERIOUSLY MADE FOR FUN.":"HECHOS MUY EN SERIO PARA DIVERTIRSE.","Your language preference is stored in your browser when supported. A language code may also appear in page URLs to keep it while navigating. B4~M4L does not use this preference for profiling.":"La preferencia de idioma se guarda en el navegador cuando es posible. Un código de idioma puede aparecer también en las URL para conservarla al navegar. B4~M4L no usa esta preferencia para crear perfiles."},"fr":{"MAX FOR LIVE DEVICES.":"DEVICES MAX FOR LIVE.","DOCUMENTATION, CHANGELOGS AND EVERYTHING YOU NEED TO KNOW. WITHOUT THE FLUFF.":"DOCUMENTATION, JOURNAUX DES MODIFICATIONS ET TOUT L’ESSENTIEL. SANS BLABLA.","Explore the device":"Découvrir le device","CORE IMAGE PENDING":"IMAGE CORE À VENIR","CORE SCREENSHOT / PENDING":"CAPTURE CORE / À VENIR","Testing · Staging · Not distributed":"Tests · Prépublication · Non distribué","TESTING · STAGING · NOT DISTRIBUTED":"TESTS · PRÉPUBLICATION · NON DISTRIBUÉ","Two distinct modulation signals from audio: one follows the moment, the other follows the time it lasts.":"Deux signaux de modulation audio distincts : l’un suit l’instant, l’autre sa durée.","← ALL DEVICES":"← TOUS LES DEVICES","SHOP":"BOUTIQUE","Shop":"Boutique","PRIVACY":"CONFIDENTIALITÉ","HELP":"AIDE","SUPPORT":"ASSISTANCE","Support":"Assistance","Quick":"Démarrage","Quick start":"Démarrage rapide","Trouble":"Problèmes","Troubleshooting":"Dépannage","Under":"Technique","Under the hood":"Sous le capot","Layers":"Couches","Params":"Paramètres","Parameters":"Paramètres","Color":"Couleur","Library":"Bibliothèque","Performance":"Performances","Main":"Principal","Time":"Temps","Behaviors":"Comportements","Mapping":"Mappage","Rendering":"Rendu","01 / REQUIREMENTS":"01 / PRÉREQUIS","COMPATIBILITY":"COMPATIBILITÉ","02 / VERSION HISTORY":"02 / HISTORIQUE DES VERSIONS","HELP & GUIDES ↓":"AIDE ET GUIDES ↓","CHANGELOG":"JOURNAL DES MODIFICATIONS","PUBLIC RELEASE NOTES":"NOTES DE VERSION PUBLIQUES","REPORT AN ISSUE":"SIGNALER UN PROBLÈME","Report an issue or get in touch.":"Signaler un problème ou me contacter.","Having trouble with INDEX HTML BRIDGE? Get in touch.":"Un problème avec INDEX HTML BRIDGE ? Contactez-moi.","Having trouble with CONSEQUENCE OF TIME? Get in touch.":"Un problème avec CONSEQUENCE OF TIME ? Contactez-moi.","DEVICE SCREENSHOT / PENDING":"CAPTURE DU DEVICE / À VENIR","MAXFORLIVE PROFILE":"PROFIL MAXFORLIVE","TEST ENVIRONMENT":"ENVIRONNEMENT DE TEST","PLATFORM":"PLATEFORME","DAW":"STAN","RUNTIME":"ENVIRONNEMENT","Not yet cleared":"Pas encore validée","Two independent modulation signals from one audio input: A follows intensity, B grows with recognized contact time. Shape both in Ableton Live.":"Deux signaux de modulation indépendants depuis une seule entrée audio : A suit l’intensité, B progresse avec la durée du contact détecté. Façonnez-les dans Ableton Live.","Established development target; exact minimum release version is not certified.":"Environnement de développement de référence ; version minimale exacte non certifiée.","Intel and Apple Silicon environments have been used in development. This candidate still requires acceptance. Windows untested.":"Développement sur Mac Intel et Apple Silicon ; cette version candidate reste à valider. Windows non testé.","0.1.5.0 tested partially with Live 12.4.2 and bundled Max 9.1.4. These are not certified minimum requirements.":"0.1.5.0 testé partiellement avec Live 12.4.2 et Max 9.1.4 intégré. Il ne s’agit pas d’exigences minimales certifiées.","macOS development testing":"Tests de développement sous macOS","Apple Silicon tests on 0.1.5.0 are partial. Separate Intel tests apply to 0.1.4.3, not this candidate. Windows untested.":"Les tests Apple Silicon de 0.1.5.0 sont partiels. Les tests Intel concernent 0.1.4.3 et non cette version candidate. Windows non testé.","Packaging, portability and redistribution requirements remain unresolved. No public release is being offered here.":"Le packaging, la portabilité et la redistribution restent à vérifier. Aucune version publique n’est proposée ici.","No publicly distributed release has been verified for this documentation snapshot. The manual below references the":"Aucune version publique n’est confirmée pour cette documentation. Le manuel ci-dessous concerne","0.23.9-rc.3 testing candidate":"version candidate de test 0.23.9-rc.3","; release candidate notes are not published as commercial release history.":"; les notes des versions candidates ne constituent pas un historique commercial.","No public release is currently confirmed. This documentation is a":"Aucune version publique n’est confirmée. Cette documentation est un","draft based on testing candidate 0.1.5.0":"brouillon basé sur la version candidate 0.1.5.0","; internal milestones are deliberately excluded from public release notes.":"; les jalons internes sont volontairement exclus des notes publiques.","Documentation draft — review before first public release.":"Brouillon documentaire — à relire avant publication.","WEBSITE":"SITE WEB","HOSTING":"HÉBERGEMENT","EXTERNAL SERVICES":"SERVICES EXTERNES","LANGUAGE PREFERENCE":"PRÉFÉRENCE LINGUISTIQUE","SUPPORT EMAIL":"E-MAIL D’ASSISTANCE","CONTROLLER / CONTACT":"RESPONSABLE / CONTACT","B4~M4L is a static documentation website. The current site code contains no first-party analytics, advertising pixels, forms or user accounts.":"B4~M4L est un site de documentation statique. Il n’utilise ni statistiques internes, ni pixels publicitaires, ni formulaires, ni comptes utilisateur.","The site is intended to be hosted with GitHub Pages. GitHub may process visitor data, including IP addresses, under its own privacy statement.":"Le site sera hébergé par GitHub Pages. GitHub peut traiter les données des visiteurs, notamment les adresses IP, conformément à sa politique de confidentialité.","GitHub Privacy Statement":"Politique de confidentialité de GitHub","The REPORT AN ISSUE button opens your email application using a prefilled message. B4~M4L does not automatically transmit attachments or diagnostics. Any information you choose to send by email is handled through the email services involved.":"Le bouton SIGNALER UN PROBLÈME ouvre votre application de messagerie avec un texte prérempli. B4~M4L n’envoie automatiquement ni pièces jointes ni diagnostics. Les informations envoyées sont traitées par les services de messagerie concernés.","Development reference only · final installation workflow to be verified on the distributed build.":"Référence de développement : l’installation finale devra être vérifiée sur la version distribuée.","Send some audio":"Envoyer un signal audio","Load COT onto an audio track in Live, or select an external sidechain source.":"Chargez COT sur une piste audio dans Live ou choisissez une source sidechain externe.","Watch A and B":"Observer A et B","A follows current intensity. B develops while contact is recognized.":"A suit l’intensité actuelle. B évolue tant que le contact est détecté.","Shape the signals":"Façonner les signaux","Use AUDIO to set A response. Use TIME for Window, Growth, Accel and B Attack/Hold/Decay.":"Utilisez AUDIO pour la réponse de A et TIME pour Window, Growth, Accel et Attack/Hold/Decay de B.","Map two destinations":"Mapper deux destinations","Assign A and B separately in Live, and compare Mod with Remote behavior.":"Assignez A et B séparément dans Live et comparez Mod et Remote.","Try behaviors":"Essayer les comportements","Start in CLEAN, then explore the seven other modes and their Time Amount controls.":"Commencez avec CLEAN, puis explorez les sept autres modes et leurs contrôles Time Amount.","Two independent modulation signals, one shared audio input.":"Deux signaux de modulation indépendants, une entrée audio commune.","A / Audio Signal":"A / Signal audio","B / Time Signal":"B / Signal temporel","Tracks audio intensity via an envelope follower. A ranges from 0 to 1 and responds relatively quickly to changes in the source.":"Suit l’intensité par un suiveur d’enveloppe. A varie de 0 à 1 et réagit assez rapidement aux changements de source.","Accumulates recognized contact time. B also ranges from 0 to 1, but follows its own time engine, hold and decay.":"Accumule la durée du contact détecté. B varie aussi de 0 à 1, mais suit son propre moteur temporel, avec hold et decay.","The scope":"L’affichage","The two traces represent separate signals; they are not combined. MIXED / Output C is not implemented in the documented testing build.":"Les deux courbes montrent des signaux distincts, sans combinaison. MIXED / Output C n’est pas implémenté dans cette version de test.","Shape the audio-responsive signal A.":"Façonnez le signal A réactif à l’audio.","Audio source":"Source audio","Use the main track input or select an external sidechain. Check routing when nothing moves.":"Utilisez l’entrée de la piste ou une sidechain externe. Si rien ne bouge, vérifiez le routage.","Adjust incoming level before the signal is analyzed.":"Réglez le niveau d’entrée avant l’analyse.","Set how quickly signal A reacts to increasing and decreasing audio intensity. These controls do not modify B Attack, Hold or Decay.":"Réglez la vitesse de réaction de A à la hausse et à la baisse de l’intensité. Cela ne modifie pas Attack, Hold ni Decay de B.","Adjust the amount applied to normalized A. It is not the contact threshold used by the time engine.":"Réglez l’intensité appliquée à A normalisé. Ce n’est pas le seuil de contact du moteur temporel.","Build a time-driven signal B from recognized contact.":"Construisez le signal temporel B à partir du contact détecté.","Contact threshold":"Seuil de contact","audio-intensity threshold (%)":"seuil d’intensité audio (%)","Allows short gaps beneath the threshold without immediately ending contact. After contact really ends, B proceeds to Hold and then Decay.":"Autorise de courtes interruptions sous le seuil sans mettre fin au contact. Après sa fin réelle, B passe à Hold puis à Decay.","Choose BEATS (musical tempo) or TIME (elapsed time) as the accumulation window; the two modes retain separate values.":"Choisissez BEATS (tempo musical) ou TIME (temps écoulé) comme fenêtre d’accumulation ; les deux modes conservent leurs valeurs propres.","Growth changes accumulation rate. Negative Accel gradually slows forward progress without reversing time. The reference build uses an Accel range of −4…+4.":"Growth modifie la vitesse d’accumulation. Un Accel négatif ralentit progressivement sans inverser le temps. La plage Accel est de −4 à +4.","Set initial signal level and range of movement.":"Définissez le niveau initial et l’amplitude du mouvement du signal.","Attack smooths growth, Hold keeps the value after contact is lost, Decay returns B toward zero.":"Attack lisse la montée, Hold maintient la valeur après la perte de contact et Decay ramène B vers zéro.","Eight ways to reshape B over time.":"Huit façons de transformer B dans le temps.","Pure time evolution. Time Amount has no effect in CLEAN.":"Évolution temporelle pure. Time Amount n’a aucun effet en mode CLEAN.","Changes movement range in response to intensity.":"Modifie l’amplitude du mouvement selon l’intensité.","Changes accumulation speed in response to intensity.":"Modifie la vitesse d’accumulation selon l’intensité.","Adds signal-dependent irregular fluctuations.":"Ajoute des fluctuations irrégulières dépendant du signal.","May produce a descending positive curve, not negative output; transitions can be abrupt.":"Peut produire une courbe positive descendante, et non une sortie négative ; les transitions peuvent être abruptes.","Can pause time progress when intensity meets its condition.":"Peut suspendre l’évolution temporelle lorsque la condition d’intensité est remplie.","Quantizes the time signal into discrete steps.":"Quantifie le signal temporel en paliers distincts.","Combines speed changes and irregular fluctuations. Time Amount adjusts each active behavior, not the basic B Depth.":"Combine changements de vitesse et fluctuations irrégulières. Time Amount règle chaque comportement actif, pas la valeur B Depth de base.","Connect A and B to separate Live destinations.":"Reliez A et B à des destinations Live distinctes.","A and B mapping":"Mappage A et B","Map A and B independently to parameters in Ableton Live using the device mapping controls.":"Assignez A et B indépendamment aux paramètres de Live avec les contrôles de mappage du device.","Mod works as relative modulation around a parameter base value. Remote takes exclusive control of its destination. These are native Ableton behaviors.":"Mod module relativement à la valeur de base du paramètre. Remote prend le contrôle exclusif de la destination. Ce sont des comportements natifs d’Ableton.","Save & Reload":"Sauvegarder et rouvrir","After mapping, verify actual modulation after saving and reopening the Live Set — not only that the destination name persists.":"Après le mappage, sauvegardez puis rouvrez le Live Set pour vérifier la modulation effective, pas seulement la persistance du nom de destination.","Distribution note":"Note sur la distribution","The referenced testing build uses native Ableton mapping abstractions with unresolved distribution/portability requirements. Do not use it as an installation guide for a public release.":"Cette version de test utilise des abstractions de mappage Ableton dont la distribution et la portabilité restent à vérifier. Ce n’est pas un guide d’installation public.","Choose a separate source for audio analysis.":"Choisissez une source distincte pour l’analyse audio.","Main audio":"Audio principal","External sidechain":"Sidechain externe","Choose an appropriate external source in Live, confirm routing, then watch the two traces in MAIN.":"Choisissez une source externe dans Live, vérifiez le routage puis observez les deux courbes dans MAIN.","Reference layout":"Disposition de référence","The sidechain panel appears to the right in 0.1.5.0. Its planned relocation is not reflected in this guide.":"Dans la 0.1.5.0, le panneau sidechain est à droite. Son déplacement prévu n’est pas encore documenté ici.","Common checks for signal, timing and mapping.":"Vérifications courantes du signal, du temps et du mappage.","No signal movement":"Aucun mouvement du signal","Confirm that audio is present, inspect source and routing, increase Gain as appropriate, and check the contact threshold and B Depth.":"Vérifiez la présence d’audio, la source et le routage ; ajustez Gain, le seuil de contact et B Depth.","A moves but B does not":"A bouge, mais pas B","Check the threshold and Tolerance, the Window, Growth, B Start/Depth and whether sufficient contact time has accumulated.":"Vérifiez le seuil, Tolerance, Window, Growth, B Start/Depth et l’accumulation d’une durée de contact suffisante.","Mapping looks static":"Le mappage semble statique","In Mod mode, the base knob may stay at its set value while modulation operates. Check the destination response, not only the knob position.":"En mode Mod, le potentiomètre de base peut rester fixe pendant la modulation. Vérifiez la réaction de la destination, pas seulement le potentiomètre.","Migration to another Mac":"Migration vers un autre Mac","Portability has not been cleared for 0.1.5.0. Do not treat the development patch as an installer or redistribution package.":"La portabilité de 0.1.5.0 n’est pas validée. Le patch de développement n’est ni un installeur ni un paquet redistribuable.","How the two modulation signals differ.":"La différence entre les deux signaux de modulation.","A: amplitude response":"A : réponse en amplitude","The envelope follower translates the level of the input signal into a continuous normalized modulation output.":"Le suiveur d’enveloppe transforme le niveau d’entrée en une modulation continue et normalisée.","B: duration response":"B : réponse à la durée","Contact recognition drives a separate time engine. Window, Growth, Accel, Hold, Decay and Behavior change the shape of B.":"La détection de contact pilote un moteur temporel distinct. Window, Growth, Accel, Hold, Decay et Behavior façonnent B.","No Output C yet":"Pas encore de sortie C","MAIN displays separate A and B traces. A blended third modulation signal is a future idea, not a current feature.":"MAIN affiche A et B séparément. Un troisième signal combiné est une idée future, pas une fonction actuelle.","Audio transparency":"Transparence audio","Help manifest unavailable.":"Manifeste HELP indisponible.","Open this page through the B4~M4L local server or check that the documentation manifest is present.":"Ouvrez cette page via le serveur local B4~M4L ou vérifiez la présence du manifeste de documentation.","Pick a layer":"Choisir une couche","Open L1–L5. Only one Layer editor is open at a time.":"Ouvrez L1–L5. Un seul éditeur de couche peut être ouvert à la fois.","Choose a tool":"Choisir un outil","Select it from the library, check its status, then LOAD / UPDATE / DOWNLOAD explicitly.":"Sélectionnez-le dans la bibliothèque, vérifiez son état, puis lancez LOAD / UPDATE / DOWNLOAD.","Shape it":"Le façonner","Open PARAMETERS, COLORS & BLEND and MIDI MAPPING in any combination.":"Ouvrez PARAMETERS, COLORS & BLEND et MIDI MAPPING selon vos besoins.","Render live":"Générer en direct","RENDER opens the external Chromium compositor. Your five Layers are combined there.":"RENDER ouvre le compositeur externe Chromium, où les cinq couches sont combinées.","Five independent visual slots, composed from L1 upward. Effects process only what sits below them.":"Cinq couches visuelles indépendantes, composées à partir de L1. Les effets traitent uniquement les couches inférieures.","One editor, five layers":"Un éditeur, cinq couches","Tool loading":"Chargement d’outil","Generator vs effect":"Générateur ou effet","Remembered per layer":"Mémoire par couche","Native Live parameters":"Paramètres Live natifs","Reset & defaults":"Réinitialisation et valeurs par défaut","Effective values":"Valeurs effectives","Automation stays yours":"L’automation reste intacte","Colors & Blend":"Couleurs et fusion","Effect Layers do not use generator blend in the same way: their shader processes the lower composite directly.":"Les couches d’effet n’utilisent pas le mode de fusion comme les générateurs : leur shader traite directement la composition inférieure.","MIDI Mapping":"Mappage MIDI","Map NOTE or CC directly onto P01–P12 with amount and envelope/smoothing controls.":"Assignez NOTE ou CC directement à P01–P12 avec intensité et enveloppe/lissage.","CHECK INDEX compares your local HTML tools with the INDEX catalogue. Nothing updates by itself.":"CHECK INDEX compare les outils HTML locaux au catalogue INDEX. Rien ne se met à jour automatiquement.","Status":"État","Selected tool":"Outil sélectionné","Requirements":"Prérequis","Live output":"Sortie en direct","Live Render Performance":"Performances du rendu live","Automatic panel":"Panneau automatique","Read the monitor":"Lire le moniteur","Same view, different quality":"Même cadrage, qualité différente","1 · Acquire":"1 · Acquisition","2 · Replay":"2 · Relecture","3 · Encode":"3 · Encodage","Current build note":"Note sur la version actuelle","Files and diagnostic reports":"Fichiers et rapports de diagnostic","Current output options":"Options de sortie actuelles","Second pass":"Deuxième passe","Files":"Fichiers","Video audio":"Audio de la vidéo","Testing status":"État des tests","The useful failure boundaries, current limitations and what not to expect from this build.":"Les principaux cas d’échec, les limites actuelles et ce que cette version ne fait pas.","macOS security":"Sécurité macOS","Clock and incomplete range":"Horloge et plage incomplète","No final file / incomplete cleanup":"Fichier final absent / nettoyage incomplet","Browser or missing resources":"Navigateur ou ressources manquantes","Current limitations":"Limites actuelles","Only if you care: how Max, Node and Chromium divide the work.":"Pour aller plus loin : la répartition du travail entre Max, Node et Chromium.","No Jitter renderer":"Pas de rendu Jitter","INDEX HTML stays browser-native. The fundamental split is simple: Max decides what happens; the browser decides how to draw it.":"INDEX HTML reste natif du navigateur : Max décide de ce qui se passe ; le navigateur décide comment l’afficher.","Links to":"Liens vers","and third-party websites open independent services. Their own privacy policies apply when you visit them. If you follow a link to Apple, see the":"et d’autres sites renvoient vers des services indépendants dont les politiques s’appliquent. Pour les liens Apple, consultez la","Apple Privacy Policy":"Politique de confidentialité d’Apple","Matteo Belgiovine — Turin, Italy ·":"Matteo Belgiovine — Turin, Italie ·","Open one Layer editor at a time. Layer visibility is independent from whether its editor is open.":"Ouvrez un éditeur de couche à la fois. La visibilité d’une couche ne dépend pas de l’ouverture de son éditeur.","Choosing a tool in the dropdown only selects it. Press LOAD to use the selection. A new LOAD restores manifest defaults. Keep tools/ and the complete device folder together; local INDEX_TOOL RC2 and legacy SKETCH_TOOL files work offline.":"Le menu ne fait que sélectionner l’outil : appuyez sur LOAD. Un nouveau LOAD restaure les valeurs par défaut du manifeste. Conservez tools/ avec le dossier complet ; INDEX_TOOL RC2 et les anciens SKETCH_TOOL fonctionnent hors ligne.","Generators draw their own canvas. Effects receive the composite of the Layers beneath them and process that result.":"Les générateurs dessinent sur leur propre canvas. Les effets traitent la composition des couches inférieures.","Each Layer remembers its section visibility. Saving a Live Set also stores the loaded tools, native values, HEX, mappings and device settings. Changing a tool resets its values: there is no separate preset memory for every tool. Keep the local tool files available when reopening a Set.":"Chaque couche mémorise ses sections ouvertes. Le Live Set conserve outils chargés, valeurs natives, HEX, mappages et réglages. Changer d’outil rétablit ses valeurs : pas de mémoire de preset par outil. Conservez les fichiers locaux pour rouvrir le Set.","Twelve numeric slots per Layer, mapped to each tool’s own manifest labels and ranges.":"Douze emplacements numériques par couche, avec noms et plages définis par le manifeste de l’outil.","The device exposes a stable Live parameter registry for automation and external modulation.":"Le device expose un registre stable de paramètres Live pour l’automation et la modulation externe.","Use the single reset beside a parameter for that control only. DEFAULT restores the loaded tool’s manifest defaults.":"Le reset près d’un paramètre n’agit que sur ce contrôle. DEFAULT restaure les valeurs du manifeste de l’outil chargé.","Up to four tool-defined colors, independent opacity and per-Layer blend mode.":"Jusqu’à quatre couleurs définies par l’outil, opacité indépendante et mode de fusion par couche.","Each active color can be edited with the picker or six-digit HEX input. Unused manifest slots stay clearly marked.":"Modifiez chaque couleur active avec le sélecteur ou un HEX à six chiffres. Les emplacements inutilisés restent indiqués.","Color opacity is a native host control and does not consume P01–P12. Missing host opacity keeps the standalone tool behaviour unchanged.":"L’opacité est un contrôle natif de l’hôte, sans utiliser P01–P12. En son absence, le comportement autonome de l’outil reste inchangé.","Velocity becomes the modulation peak. Attack rises to that peak, then release returns automatically to zero.":"La vélocité définit le pic de modulation. Attack l’atteint, puis Release revient automatiquement à zéro.","The incoming 0–127 value becomes the target. Attack smooths upward movement; release smooths downward movement.":"La valeur CC entrante (0–127) devient la cible. Attack lisse la montée et Release la descente.","Refreshes the remote catalogue and compares it with the flat local":"Actualise le catalogue distant et le compare à la bibliothèque locale","library. It does not download tools automatically.":": aucun outil n’est téléchargé automatiquement.","Depending on state, the action becomes LOAD, UPDATE or DOWNLOAD. A dropdown selection alone never changes the running Layer.":"Selon l’état, l’action devient LOAD, UPDATE ou DOWNLOAD. Choisir dans le menu ne change jamais la couche active à lui seul.","Queues only MISSING and OUTDATED catalogue tools. CURRENT entries are left untouched; local-only fixtures remain local.":"Met en file uniquement les outils MISSING et OUTDATED. Les CURRENT restent inchangés et les éléments locaux restent locaux.","Local library information loading…":"Chargement de la bibliothèque locale…","A ready local Node host, a supported installed Chromium browser and compatible Canvas/WebGL support are required.":"Il faut un hôte Node local prêt, un navigateur Chromium compatible et Canvas/WebGL.","In the 0.1.5.0 reference build, the control labelled Time Gate is an":"Dans la version 0.1.5.0, le contrôle Time Gate est un",", not a minimum contact duration. This naming is scheduled for revision.":", et non une durée minimale de contact. Ce nom doit être revu.","The native dial shows the Live-owned control and Live’s external modulation. The black field shows the final value sent to the tool, including INDEX MIDI, clamped and quantized to the manifest range. With INDEX MIDI assigned that field is grey; it can differ from the dial. No custom MIDI arc is painted over Live’s native display.":"Le potentiomètre natif affiche le contrôle géré par Live et sa modulation externe. Le champ noir affiche la valeur finale transmise à l’outil, avec INDEX MIDI, limitée et quantifiée selon le manifeste. Avec INDEX MIDI assigné, ce champ devient gris et peut différer du potentiomètre. Aucun arc MIDI personnalisé ne recouvre l’affichage natif de Live.","The base Live parameter remains the automation/modulation target. MAP ABS and MAP % are the external Live modulator’s mapping/range modes. Choose them in the modulator; INDEX receives its native parameter output. INDEX does not reinterpret either mode or write the effective MIDI result back into the parameter. ABS ↔ % visual behavior in this candidate still requires native Max/Live testing.":"Le paramètre Live de base reste la cible de l’automation/modulation. MAP ABS et MAP % sont des modes de mappage/plage du modulateur Live externe : choisissez-les dans ce modulateur. INDEX reçoit la sortie native du paramètre, n’interprète pas ces modes et ne réécrit pas le résultat MIDI effectif. Le comportement visuel ABS ↔ % doit encore être testé dans Max/Live.","Mappings start unassigned. Choose the MIDI input and channel, then a slot source and NOTE/CC ID. NONE unassigns a slot. Amount sets the contribution; attack/release shape its response. Assignments are Layer-specific and saved with the Set; the functional Live controls keep their automation identities.":"Les mappages sont initialement vides. Choisissez l’entrée, le canal MIDI, la source d’emplacement et l’ID NOTE/CC. NONE supprime une assignation. Amount règle la contribution, Attack/Release la réponse. Les assignations sont propres à chaque couche et sauvegardées dans le Set ; les contrôles Live conservent leurs identités d’automation.","RENDER launches the localhost compositor in an external Chromium app window. Live state reaches one compositor SSE connection, then the five tool iframes through":"RENDER lance le compositeur localhost dans une fenêtre Chromium externe. L’état Live passe par une connexion SSE vers le compositeur, puis vers les cinq iframes grâce à","Actual / target FPS shows completed visual frames. The display-only dial fills up to the target and cannot be edited. FRAME CADENCE reports the observed interval between completed frames in milliseconds, not GPU execution time. PREVIEW shows the effective buffer dimensions.":"Actual / target FPS affiche les images visuelles terminées. Le potentiomètre est purement indicatif, se remplit jusqu’à la cible et ne peut pas être modifié. FRAME CADENCE indique l’intervalle entre images terminées en millisecondes, pas le temps GPU. PREVIEW affiche la taille effective du tampon.","AUTO follows browser / display-driven cadence; its target is estimated (~). Fixed settings request a maximum of 30 or 60 FPS across the hosted tools and compositor. Actual FPS can be lower with heavier tools.":"AUTO suit la cadence du navigateur/écran ; sa cible est estimée (~). Les réglages fixes demandent un maximum de 30 ou 60 FPS pour outils et compositeur. Les FPS réels peuvent être inférieurs avec des outils plus lourds.","AUTO keeps window-dependent rendering. Fixed presets control pixel workload: 1280 × 720, 1920 × 1080, 2560 × 1440 or 3840 × 2160 in a 16:9 window. Other window shapes keep their framing and fill the window, using a buffer that fits within the preset dimensions. PREVIEW reports the actual size; Retina does not multiply a fixed preset.":"AUTO adapte le rendu à la fenêtre. Les préréglages fixes limitent la charge en pixels à 1280 × 720, 1920 × 1080, 2560 × 1440 ou 3840 × 2160 en 16:9. Les autres formats conservent le cadrage et remplissent la fenêtre avec un tampon dans les limites du préréglage. PREVIEW affiche la taille réelle ; Retina ne multiplie pas un préréglage fixe.","The full composition scales to the RENDER window without zooming or cropping when RES changes. Settings survive closing and reopening RENDER and are saved with the Live Set. A new unconfigured device starts from AUTO / AUTO. If a buffer is unsupported, INDEX reports the error and restores the preceding selection.":"La composition entière s’adapte à RENDER sans zoom ni recadrage quand RES change. Les réglages survivent à la fermeture et sont enregistrés dans le Live Set. Un nouveau device démarre en AUTO / AUTO. Si un tampon n’est pas pris en charge, INDEX signale l’erreur et restaure le choix précédent.","Completed videos appear directly in":"Les vidéos terminées se trouvent directement dans","if Live cannot provide a saved Set name. Collisions add _02, _03…; existing files are never overwritten. Active work stays in":"si Live ne peut pas fournir un nom de Set enregistré. En cas de conflit, _02, _03… sont ajoutés ; aucun fichier existant n’est écrasé. Le travail en cours reste dans",". Reports stay in":". Les rapports restent dans","; they may contain local paths, tool names and project information. The Bridge never sweeps old jobs or reports.":"; ils peuvent contenir des chemins locaux, des noms d’outils et des informations de projet. Le Bridge n’efface jamais globalement les anciens traitements ou rapports.","; the finalizer trims and validates a separate":"; le module final coupe et valide un fichier séparé","when the complete range passes.":"lorsque toute la plage passe la validation.","Loading current audio status…":"Chargement de l’état actuel de l’audio…","If macOS blocks a trusted, verified executable because its developer cannot be verified, follow":"Si macOS bloque un exécutable fiable et vérifié dont le développeur ne peut pas être identifié, consultez","macOS security: opening blocked applications":"sécurité macOS : ouvrir des applications bloquées","Keep the complete folder together, load a local tool, and confirm Chromium is installed. RENDER opens an isolated app-style Chromium window; HELP uses the normal browser. Missing tool/module/font errors need the exact Console message and package version. CHECK refreshes metadata without replacing HTML; UPDATE explicitly downloads a selected tool.":"Conservez le dossier complet, chargez un outil local et vérifiez Chromium. RENDER ouvre une fenêtre Chromium isolée, HELP le navigateur habituel. En cas d’outil/module/police manquant, conservez le message exact de console et la version du paquet. CHECK actualise les métadonnées sans remplacer le HTML ; UPDATE télécharge explicitement l’outil choisi.","SERIOUSLY MADE FOR FUN.":"CRÉÉS SÉRIEUSEMENT POUR LE PLAISIR.","Your language preference is stored in your browser when supported. A language code may also appear in page URLs to keep it while navigating. B4~M4L does not use this preference for profiling.":"Votre langue est conservée dans le navigateur lorsque cela est possible. Un code de langue peut aussi apparaître dans l’URL pour maintenir la sélection pendant la navigation. B4~M4L ne l’utilise pas pour établir des profils."}};

// V0.7: additions for new explanatory text.
Object.assign(translations["it"], {"The library compares the files installed locally with the INDEX catalogue. These labels explain each possible result:": "La libreria confronta i file installati in locale con il catalogo INDEX. Queste etichette spiegano i possibili risultati:"});
Object.assign(translations["de"], {"The library compares the files installed locally with the INDEX catalogue. These labels explain each possible result:": "Die Bibliothek vergleicht lokal installierte Dateien mit dem INDEX-Katalog. Diese Bezeichnungen erläutern die möglichen Ergebnisse:"});
Object.assign(translations["es"], {"The library compares the files installed locally with the INDEX catalogue. These labels explain each possible result:": "La biblioteca compara los archivos instalados localmente con el catálogo INDEX. Estas etiquetas explican los posibles resultados:"});
Object.assign(translations["fr"], {"The library compares the files installed locally with the INDEX catalogue. These labels explain each possible result:": "La bibliothèque compare les fichiers installés localement au catalogue INDEX. Ces libellés expliquent les résultats possibles:"});
const supported=['en','it','de','es','fr'];
const storeKey='b4m4l.language';
const noticePrefix='b4m4l.translation-notice.';
const shownThisDocument=new Set();
const nav=()=>{try{return new URLSearchParams(location.search).get('lang')}catch(e){return null}};
const load=()=>{try{return localStorage.getItem(storeKey)}catch(e){try{return sessionStorage.getItem(storeKey)}catch(e2){return null}}};
let locale=supported.includes(nav())?nav():supported.includes(load())?load():'en';
const original=new WeakMap();
function translate(node){
 if(!node||node.nodeType!==3||!node.parentNode)return;
 const parent=node.parentNode;
 if(parent.closest&&parent.closest('script,style,code,pre,textarea,svg,[data-no-translate]'))return;
 const src=original.has(node)?original.get(node):node.nodeValue;
 if(!original.has(node))original.set(node,src);
 const trimmed=src.trim();if(!trimmed)return;
 const dict=translations[locale]||{};
 const translated=dict[trimmed]||trimmed;
 const left=src.match(/^\s*/)?.[0]||'',right=src.match(/\s*$/)?.[0]||'';
 const next=left+translated+right;
 if(node.nodeValue!==next)node.nodeValue=next;
}
function translateRoot(root){
 if(!root)return;
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 let n;while((n=walker.nextNode()))translate(n);
}
function translateHelp(){
 // Only HELP content is translated. Homepage, device overview, requirements, changelog and privacy stay English.
 document.querySelectorAll('.hero,.quick-start,.manual').forEach(root=>{root.lang=locale;translateRoot(root)});
}
function links(){
 document.querySelectorAll('a[href]').forEach(a=>{
  const value=a.getAttribute('href');
  if(!value||value.startsWith('mailto:')||value.startsWith('#')||value.startsWith('javascript:')||value.startsWith('http:')||value.startsWith('https:'))return;
  try{const url=new URL(value,location.href);if(url.protocol!=='file:'&&url.origin!==location.origin)return;
   if(locale==='en')url.searchParams.delete('lang');else url.searchParams.set('lang',locale);
   a.setAttribute('href',url.protocol==='file:'?url.href:(url.pathname+url.search+url.hash));
  }catch(e){}
 });
}
function updateSelect(){
 document.querySelectorAll('select[data-b4-language]').forEach(select=>{
  select.value=locale;
  const selected=select.selectedOptions?.[0]?.textContent||locale.toUpperCase();
  // Optical width in text em, with room for chevron.
  select.style.width='auto';
 });
}
function render(){
 // The overall site language is English; only the manual subsections have a different lang.
 document.documentElement.lang='en';
 updateSelect();translateHelp();links();
}
function popupOnce(){
 if(!['de','es','fr'].includes(locale))return;
 const dlg=document.getElementById('b4-translation-dialog');if(!dlg)return;
 const key=noticePrefix+locale;
 if(shownThisDocument.has(locale))return;shownThisDocument.add(locale);
 try{if(sessionStorage.getItem(key))return;sessionStorage.setItem(key,'1')}catch(e){}
 if(typeof dlg.showModal==='function')dlg.showModal();else dlg.setAttribute('open','');
}
function save(lang){
 if(!supported.includes(lang))return;
 locale=lang;
 try{localStorage.setItem(storeKey,lang)}catch(e){try{sessionStorage.setItem(storeKey,lang)}catch(e2){}}
 try{const u=new URL(location.href);if(lang==='en')u.searchParams.delete('lang');else u.searchParams.set('lang',lang);history.replaceState(history.state,'',u.href)}catch(e){}
 render();popupOnce();
}
document.querySelectorAll('select[data-b4-language]').forEach(s=>s.addEventListener('change',()=>save(s.value)));
document.querySelectorAll('[data-close-translation-dialog]').forEach(btn=>btn.addEventListener('click',()=>{const dlg=btn.closest('dialog');if(dlg?.close)dlg.close();else dlg?.removeAttribute('open')}));
const dlg=document.getElementById('b4-translation-dialog');
if(dlg)dlg.addEventListener('click',e=>{if(e.target===dlg)dlg.close?.()});
let pending=false;
const observer=new MutationObserver(muts=>{
 if(pending||!muts.some(m=>m.type==='childList'&&m.addedNodes.length))return;
 pending=true;queueMicrotask(()=>{pending=false;translateHelp();links()});
});
render();observer.observe(document.body,{subtree:true,childList:true});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',popupOnce,{once:true});else popupOnce();
})();
